import { describe, expect, it } from 'vitest';
import {
  AgenticPolicyEngine,
  checkCapabilityEnvelope,
  createLegacyCompatibleState,
  delegateEnvelope,
  isEnvelopeReduction,
  type PolicyRequest,
  type PolicyRule,
} from '../src/policy/index.js';

const request = (overrides: Partial<PolicyRequest> = {}): PolicyRequest => ({
  identity: { id: 'agent:coder', type: 'agent', roles: ['developer'] },
  action: { type: 'code.write', resource: 'src/app.ts', environment: 'development' },
  ...overrides,
});

describe('AgenticPolicyEngine', () => {
  it('preserves existing installations in legacy mode', () => {
    const engine = AgenticPolicyEngine.fromState(createLegacyCompatibleState());
    const decision = engine.evaluate(request());
    expect(decision.outcome).toBe('allowed');
    expect(decision.enforcedOutcome).toBe('allowed');
    expect(decision.reason).toBe('legacy-default-allow');
  });

  it('observes default deny without breaking the action', () => {
    const engine = new AgenticPolicyEngine({ mode: 'observe' });
    const decision = engine.evaluate(request());
    expect(decision.outcome).toBe('denied');
    expect(decision.enforcedOutcome).toBe('allowed');
  });

  it('enforces default deny and deny-overrides', () => {
    const rules: PolicyRule[] = [
      { id: 'allow-code', effect: 'allow', actions: ['code.*'] },
      { id: 'deny-production', effect: 'deny', actions: ['code.write'], environments: ['production'], priority: 10 },
    ];
    const engine = new AgenticPolicyEngine({ mode: 'enforce', rules });
    expect(engine.evaluate(request()).enforcedOutcome).toBe('allowed');
    expect(engine.evaluate(request({
      action: { type: 'code.write', resource: 'src/app.ts', environment: 'production' },
    })).enforcedOutcome).toBe('denied');
  });

  it('requires signed tool evidence when a rule asks for it', () => {
    const engine = new AgenticPolicyEngine({
      mode: 'enforce',
      evidenceVerifier: (evidence) => evidence.signature === 'valid-test-signature',
      rules: [{
        id: 'verified-deploy',
        effect: 'allow',
        actions: ['deployment.promote'],
        constraints: { requireSignedEvidence: true, requiredProvenance: ['tool_result'] },
      }],
    });
    const base = request({ action: { type: 'deployment.promote', environment: 'production' } });
    expect(engine.evaluate(base).enforcedOutcome).toBe('denied');
    expect(engine.evaluate({
      ...base,
      context: { evidence: [{
        id: 'evidence-1',
        provenance: 'tool_result',
        signed: true,
        signature: 'valid-test-signature',
      }] },
    }).enforcedOutcome).toBe('allowed');
    expect(engine.evaluate({
      ...base,
      context: { evidence: [{ id: 'fake', provenance: 'tool_result', signed: true }] },
    }).enforcedOutcome).toBe('denied');
    expect(engine.evaluate({
      ...base,
      context: {
        evidence: [
          { id: 'verified-wrong-type', provenance: 'user_claim', signature: 'valid-test-signature' },
          { id: 'unsigned-right-type', provenance: 'tool_result' },
        ],
      },
    }).enforcedOutcome).toBe('denied');
  });

  it('requires a scoped human approval and forbids self approval', () => {
    const engine = new AgenticPolicyEngine({
      mode: 'enforce',
      now: () => 1_000,
      approvalIssuerVerifier: (issuer) => issuer === 'user:release-manager',
      rules: [{ id: 'prod-approval', effect: 'require_approval', actions: ['deployment.promote'] }],
    });
    expect(() => engine.issueApproval({
      id: 'self',
      principal: 'agent:coder',
      actions: ['deployment.promote'],
      issuedBy: 'agent:coder',
      expiresAt: 2_000,
      maxUses: 2,
    })).toThrow('self-approval-forbidden');
    engine.issueApproval({
      id: 'human-1',
      principal: 'agent:coder',
      actions: ['deployment.promote'],
      issuedBy: 'user:release-manager',
      expiresAt: 2_000,
      maxUses: 1,
    });
    const deploy = request({
      action: { type: 'deployment.promote', resource: 'prod' },
      context: { approvalIds: ['human-1'], now: 1_100 },
    });
    expect(engine.evaluate(deploy).reason).toBe('approved-by:human-1');
    expect(engine.evaluate(deploy).enforcedOutcome).toBe('approval_required');
  });

  it('uses authority time and rejects ambiguous approval accounting', () => {
    let authorityNow = 2_000;
    const engine = new AgenticPolicyEngine({
      mode: 'enforce',
      now: () => authorityNow,
      approvalIssuerVerifier: () => true,
      rules: [{ id: 'approval', effect: 'require_approval', actions: ['deploy'] }],
    });
    engine.issueApproval({
      id: 'approval-1',
      principal: 'agent:coder',
      actions: ['deploy'],
      issuedBy: 'user:admin',
      issuedAt: 1_000,
      expiresAt: 3_000,
      maxUses: 1,
    });
    expect(() => engine.issueApproval({
      id: 'approval-1',
      principal: 'agent:coder',
      actions: ['deploy'],
      issuedBy: 'user:admin',
      issuedAt: 1_000,
      expiresAt: 3_000,
      maxUses: 1,
    })).toThrow('duplicate-approval-id');
    expect(() => engine.issueApproval({
      id: 'bad-uses',
      principal: 'agent:coder',
      actions: ['deploy'],
      issuedBy: 'user:admin',
      issuedAt: 1_000,
      expiresAt: 3_000,
      maxUses: 1,
      uses: -1,
    })).toThrow('invalid-approval');
    expect(engine.evaluate(request({
      action: { type: 'deploy' },
      context: { approvalIds: ['approval-1'], now: 0 },
    })).enforcedOutcome).toBe('allowed');
    authorityNow = 4_000;
    expect(engine.evaluate(request({
      action: { type: 'deploy' },
      context: { approvalIds: ['approval-1'], now: 0 },
    })).enforcedOutcome).toBe('approval_required');
  });

  it('atomically accounts budget usage', () => {
    const engine = new AgenticPolicyEngine({
      mode: 'enforce',
      now: () => 10,
      rules: [{ id: 'allow-model', effect: 'allow', actions: ['model.call'] }],
      budgets: [{ id: 'daily', principal: 'agent:*', action: 'model.call', maxCostUsd: 1, periodMs: 86_400_000 }],
    });
    const call = request({
      action: { type: 'model.call', resource: 'openrouter', costUsd: 0.6 },
    });
    expect(engine.evaluate(call).enforcedOutcome).toBe('allowed');
    expect(engine.evaluate(call).reason).toBe('budget-exceeded:daily');
  });

  it('creates and verifies a tamper-evident receipt chain', () => {
    const engine = new AgenticPolicyEngine({ mode: 'legacy', signingKey: 'test-secret' });
    engine.evaluate(request());
    engine.evaluate(request({ action: { type: 'code.read', resource: 'README.md' } }));
    expect(engine.verifyLedger()).toEqual({ valid: true, length: 2 });

    const state = engine.exportState();
    state.receipts[0]!.payload.decision.reason = 'tampered';
    const tampered = AgenticPolicyEngine.fromState(state, { signingKey: 'test-secret' });
    expect(tampered.verifyLedger().valid).toBe(false);
  });

  it('requires configured receipt authentication in both directions', () => {
    const signed = new AgenticPolicyEngine({ mode: 'legacy', signingKey: 'test-secret' });
    signed.evaluate(request());
    const strippedState = signed.exportState();
    delete strippedState.receipts[0]!.signature;
    expect(AgenticPolicyEngine.fromState(strippedState, { signingKey: 'test-secret' }).verifyLedger().error)
      .toBe('receipt-signature-missing');

    const signedState = signed.exportState();
    expect(AgenticPolicyEngine.fromState(signedState).verifyLedger().error)
      .toBe('receipt-signing-key-required');
  });

  it('rejects negative and non-finite resource accounting', () => {
    const engine = new AgenticPolicyEngine({ mode: 'legacy' });
    expect(() => engine.evaluate(request({
      action: { type: 'model.call', costUsd: -1 },
    }))).toThrow('invalid-policy-action-costUsd');
    expect(() => engine.evaluate(request({
      action: { type: 'model.call', tokens: Number.POSITIVE_INFINITY },
    }))).toThrow('invalid-policy-action-tokens');
  });

  it('fails closed when a constrained action omits required metering', () => {
    const engine = new AgenticPolicyEngine({
      mode: 'enforce',
      rules: [{
        id: 'bounded-model',
        effect: 'allow',
        actions: ['model.call'],
        constraints: { maxCostUsd: 1, maxTokens: 1_000, maxConcurrency: 1 },
      }],
    });
    expect(engine.evaluate(request({ action: { type: 'model.call' } })).enforcedOutcome).toBe('denied');
    expect(engine.evaluate(request({
      action: { type: 'model.call', costUsd: 0.5, tokens: 500, concurrency: 1 },
    })).enforcedOutcome).toBe('allowed');
  });
});

describe('CapabilityEnvelope', () => {
  const parent = {
    actions: ['code.*'],
    resources: ['src/*'],
    tools: ['exec_command', 'apply_patch'],
    maxCostUsd: 10,
    maxConcurrency: 4,
    network: false,
    destructive: false,
    delegationDepth: 2,
    expiresAt: 2_000,
  };

  it('allows only monotonic reductions', () => {
    const child = delegateEnvelope(parent, {
      actions: ['code.write'],
      resources: ['src/app.ts'],
      tools: ['apply_patch'],
      maxCostUsd: 2,
      maxConcurrency: 2,
      network: false,
      destructive: false,
    });
    expect(isEnvelopeReduction(parent, child)).toBe(true);
    expect(child.delegationDepth).toBe(1);
    expect(() => delegateEnvelope(parent, { tools: ['github_push'] })).toThrow('capability-envelope-cannot-grow');
    const inherited = delegateEnvelope(parent, {});
    expect(inherited.actions).toEqual(parent.actions);
    expect(inherited.tools).toEqual(parent.tools);
    expect(inherited.maxCostUsd).toBe(parent.maxCostUsd);
    expect(checkCapabilityEnvelope({
      type: 'deployment.promote',
      tool: 'github_push',
    }, inherited, 1_000).allowed).toBe(false);
  });

  it('blocks actions outside the envelope before execution', () => {
    expect(checkCapabilityEnvelope({
      type: 'code.write',
      resource: 'src/app.ts',
      tool: 'apply_patch',
      concurrency: 2,
    }, parent, 1_000).allowed).toBe(true);
    expect(checkCapabilityEnvelope({
      type: 'code.write',
      resource: 'src/app.ts',
      tool: 'apply_patch',
      network: true,
    }, parent, 1_000)).toEqual({ allowed: false, reason: 'network-outside-envelope' });
  });

  it('enforces delegated envelope boundaries even in legacy mode', () => {
    const engine = new AgenticPolicyEngine({ mode: 'legacy', now: () => 1_000 });
    const decision = engine.evaluate(request({
      action: { type: 'code.write', resource: 'src/app.ts', tool: 'apply_patch', network: true },
      context: { envelope: parent },
    }));
    expect(decision.outcome).toBe('denied');
    expect(decision.enforcedOutcome).toBe('denied');
    expect(decision.reason).toBe('network-outside-envelope');
  });
});

/**
 * Tests for AgentAuthorizationPropagator (ADR-144 P1, ruvnet/ruflo#2248).
 *
 * Covers the load-bearing invariants of the action-layer security model:
 *  - wrapOutbound monotonically reduces scope (cannot grant more than holder)
 *  - delegationDepth decrements by ≥ 1 every hop; depth-0 cannot delegate
 *  - expired scopes are rejected at wrap and at check
 *  - checkToolCall returns stable, telemetry-friendly reasons
 *  - verifyServerAuth rejects empty / nullish credentials
 *  - provenance buffer ring-bound at the configured max
 *  - legacy permissive scope (the migration shim) allows everything
 */

import { describe, it, expect } from 'vitest';
import {
  AgentAuthorizationPropagator,
  AuthorizationPropagationError,
  makeLegacyPermissiveScope,
  type AuthScope,
} from '../src/authorization/propagator.js';

const FAR_FUTURE = Date.now() + 60 * 60 * 1000; // 1 hour from now

function scope(overrides: Partial<AuthScope> = {}): AuthScope {
  return {
    principalId: 'principal-A',
    grantedTools: ['memory_store', 'memory_search'],
    grantedServers: ['server-1'],
    delegationDepth: 3,
    expiresAt: FAR_FUTURE,
    ...overrides,
  };
}

describe('wrapOutbound — scope reduction invariants', () => {
  const prop = new AgentAuthorizationPropagator();

  it('decrements delegationDepth by exactly 1', () => {
    const env = prop.wrapOutbound({ msg: 'hi' }, scope({ delegationDepth: 3 }));
    expect(env.scope.delegationDepth).toBe(2);
  });

  it('refuses to delegate when depth has been exhausted', () => {
    expect(() =>
      prop.wrapOutbound({ msg: 'hi' }, scope({ delegationDepth: 0 })),
    ).toThrow(AuthorizationPropagationError);
  });

  it('refuses to grant a tool not held by the parent scope', () => {
    expect(() =>
      prop.wrapOutbound({}, scope(), { tools: ['memory_store', 'task_create'] }),
    ).toThrow(/cannot grant tools 'task_create'/);
  });

  it('allows a strict subset of the parent tool set', () => {
    const env = prop.wrapOutbound({}, scope(), { tools: ['memory_store'] });
    expect(env.scope.grantedTools).toEqual(['memory_store']);
  });

  it('preserves principalId across the hop', () => {
    const env = prop.wrapOutbound({}, scope({ principalId: 'principal-X' }));
    expect(env.scope.principalId).toBe('principal-X');
  });

  it('rejects an expired holder scope', () => {
    expect(() =>
      prop.wrapOutbound({}, scope({ expiresAt: 1 })),
    ).toThrow(/scope expired/);
  });

  it('passes the payload through untouched', () => {
    const payload = { kind: 'design', body: { topic: 'auth' } };
    const env = prop.wrapOutbound(payload, scope());
    expect(env.payload).toBe(payload);
  });

  it('a wildcard parent scope can grant any specific tool', () => {
    const env = prop.wrapOutbound({}, makeLegacyPermissiveScope(), {
      tools: ['memory_store', 'task_create'],
    });
    expect(env.scope.grantedTools).toEqual(['memory_store', 'task_create']);
  });
});

describe('checkToolCall — typed decisions', () => {
  const prop = new AgentAuthorizationPropagator();

  it('allows a tool that is in scope', () => {
    expect(prop.checkToolCall('memory_store', scope())).toEqual({ allowed: true });
  });

  it('denies a tool not in scope with stable reason', () => {
    expect(prop.checkToolCall('shell_exec', scope())).toEqual({
      allowed: false,
      reason: 'tool-not-in-scope',
    });
  });

  it('denies when the named server is not in scope', () => {
    expect(
      prop.checkToolCall('memory_store', scope(), { serverId: 'untrusted' }),
    ).toEqual({ allowed: false, reason: 'server-not-in-scope' });
  });

  it('denies an expired scope deterministically (fixed-now)', () => {
    const expired = scope({ expiresAt: 1000 });
    expect(prop.checkToolCall('memory_store', expired, { now: 2000 })).toEqual({
      allowed: false,
      reason: 'scope-expired',
    });
  });
});

describe('verifyServerAuth — fail-closed on missing credentials', () => {
  const prop = new AgentAuthorizationPropagator();

  it('rejects missing credential', () => {
    expect(prop.verifyServerAuth('s1', null)).toBe(false);
    expect(prop.verifyServerAuth('s1', undefined)).toBe(false);
  });

  it('rejects empty-string credential', () => {
    expect(prop.verifyServerAuth('s1', '')).toBe(false);
    expect(prop.verifyServerAuth('s1', '   ')).toBe(false);
  });

  it('rejects missing serverId', () => {
    expect(prop.verifyServerAuth('', 'token')).toBe(false);
  });

  it('accepts a non-empty credential (P1 permissive default)', () => {
    expect(prop.verifyServerAuth('s1', 'oauth-token-xyz')).toBe(true);
  });
});

describe('provenance buffer', () => {
  it('retains recorded actions in insertion order', () => {
    const p = new AgentAuthorizationPropagator();
    p.recordAction('agent-A', 'memory_store', scope(), 'allowed');
    p.recordAction('agent-B', 'shell_exec', scope(), 'denied', 'tool-not-in-scope');
    const log = p.getProvenance();
    expect(log).toHaveLength(2);
    expect(log[0]?.outcome).toBe('allowed');
    expect(log[1]?.reason).toBe('tool-not-in-scope');
  });

  it('ring-bounds at the configured max', () => {
    const p = new AgentAuthorizationPropagator({ provenanceBufferMax: 3 });
    for (let i = 0; i < 5; i++) p.recordAction('a', 't', scope(), 'allowed', `i=${i}`);
    const log = p.getProvenance();
    expect(log).toHaveLength(3);
    expect(log[0]?.reason).toBe('i=2');
    expect(log[2]?.reason).toBe('i=4');
  });
});

/**
 * Credential Generator Tests - CVE-3 Remediation Validation
 *
 * Tests verify:
 * - Cryptographically secure random generation
 * - No hardcoded defaults
 * - Proper entropy levels
 * - Unique credentials per generation
 */

import { describe, it, expect, beforeEach } from 'vitest';
import {
  CredentialGenerator,
  CredentialGeneratorError,
  createCredentialGenerator,
  generateCredentials,
} from '../src/credential-generator.js';

describe('CredentialGenerator', () => {
  let generator: CredentialGenerator;

  beforeEach(() => {
    generator = new CredentialGenerator();
  });

  describe('Configuration', () => {
    it('should use default configuration', () => {
      expect(() => new CredentialGenerator()).not.toThrow();
    });

    it('should reject password length below 16', () => {
      expect(() => new CredentialGenerator({
        passwordLength: 8,
      })).toThrow(CredentialGeneratorError);
    });

    it('should reject API key length below 32', () => {
      expect(() => new CredentialGenerator({
        apiKeyLength: 16,
      })).toThrow(CredentialGeneratorError);
    });

    it('should reject secret length below 32', () => {
      expect(() => new CredentialGenerator({
        secretLength: 16,
      })).toThrow(CredentialGeneratorError);
    });
  });

  describe('Password Generation', () => {
    it('should generate password of specified length', () => {
      const password = generator.generatePassword();
      expect(password.length).toBeGreaterThanOrEqual(32);
    });

    it('should generate unique passwords', () => {
      const passwords = new Set<string>();
      for (let i = 0; i < 100; i++) {
        passwords.add(generator.generatePassword());
      }
      expect(passwords.size).toBe(100);
    });

    it('should include required character types', () => {
      for (let i = 0; i < 10; i++) {
        const password = generator.generatePassword();
        expect(password).toMatch(/[A-Z]/); // Uppercase
        expect(password).toMatch(/[a-z]/); // Lowercase
        expect(password).toMatch(/\d/);    // Digit
        expect(password).toMatch(/[!@#$%^&*()_+\-=\[\]{}|;:,.<>?]/); // Special
      }
    });
  });

  describe('API Key Generation', () => {
    it('should generate API key with prefix', () => {
      const { key, prefix } = generator.generateApiKey('cf_');
      expect(key.startsWith('cf_')).toBe(true);
      expect(prefix).toBe('cf_');
    });

    it('should generate unique keys', () => {
      const keys = new Set<string>();
      for (let i = 0; i < 100; i++) {
        keys.add(generator.generateApiKey().key);
      }
      expect(keys.size).toBe(100);
    });

    it('should include keyId', () => {
      const { keyId } = generator.generateApiKey();
      // Should be a valid UUID
      expect(keyId).toMatch(/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i);
    });

    it('should include createdAt timestamp', () => {
      const { createdAt } = generator.generateApiKey();
      expect(createdAt).toBeInstanceOf(Date);
    });
  });

  describe('Secret Generation', () => {
    it('should generate hex-encoded secret', () => {
      const secret = generator.generateSecret();
      expect(secret).toMatch(/^[0-9a-f]+$/);
    });

    it('should generate secret of specified length', () => {
      const secret = generator.generateSecret(64);
      expect(secret.length).toBe(64);
    });

    it('should generate unique secrets', () => {
      const secrets = new Set<string>();
      for (let i = 0; i < 100; i++) {
        secrets.add(generator.generateSecret());
      }
      expect(secrets.size).toBe(100);
    });
  });

  describe('Encryption Key Generation', () => {
    it('should generate 32-byte (256-bit) key as hex', () => {
      const key = generator.generateEncryptionKey();
      // 32 bytes = 64 hex characters
      expect(key.length).toBe(64);
      expect(key).toMatch(/^[0-9a-f]+$/);
    });

    it('should generate unique keys', () => {
      const keys = new Set<string>();
      for (let i = 0; i < 100; i++) {
        keys.add(generator.generateEncryptionKey());
      }
      expect(keys.size).toBe(100);
    });
  });

  describe('Installation Credentials', () => {
    it('should generate complete credential set', () => {
      const credentials = generator.generateInstallationCredentials();

      expect(credentials.adminPassword).toBeDefined();
      expect(credentials.servicePassword).toBeDefined();
      expect(credentials.jwtSecret).toBeDefined();
      expect(credentials.sessionSecret).toBeDefined();
      expect(credentials.encryptionKey).toBeDefined();
      expect(credentials.generatedAt).toBeInstanceOf(Date);
    });

    it('should set expiration when specified', () => {
      const credentials = generator.generateInstallationCredentials(30);

      expect(credentials.expiresAt).toBeInstanceOf(Date);

      // Should be approximately 30 days in the future
      const expectedExpiration = Date.now() + 30 * 24 * 60 * 60 * 1000;
      const actualExpiration = credentials.expiresAt!.getTime();
      expect(Math.abs(actualExpiration - expectedExpiration)).toBeLessThan(1000);
    });

    it('should generate unique credentials each time', () => {
      const cred1 = generator.generateInstallationCredentials();
      const cred2 = generator.generateInstallationCredentials();

      expect(cred1.adminPassword).not.toBe(cred2.adminPassword);
      expect(cred1.servicePassword).not.toBe(cred2.servicePassword);
      expect(cred1.jwtSecret).not.toBe(cred2.jwtSecret);
    });
  });

  describe('Token Generation', () => {
