      const maliciousArgs = ['$(cat /etc/passwd)'];

      // When
      await safeExecutor.execute(command, maliciousArgs);

      // Then
      expect(mockSpawner.spawn).toHaveBeenCalledWith(
        'npm',
        ['cat /etc/passwd'], // $() removed
        expect.any(Object)
      );
    });

    it('should prevent shell expansion attack', async () => {
      // Given
