import { performance } from 'node:perf_hooks';
import { AgenticPolicyEngine, evaluatePolicy } from '../dist/policy/index.js';

const iterations = Number(process.env.POLICY_BENCH_ITERATIONS ?? 50_000);
const request = {
  identity: { id: 'agent:benchmark', type: 'agent', roles: ['developer'] },
  action: { type: 'code.write', resource: 'src/app.ts', environment: 'development' },
  context: {
    envelope: {
      actions: ['code.*'],
      resources: ['src/*'],
      maxConcurrency: 4,
      network: false,
      destructive: false,
    },
  },
};
const rules = [
  { id: 'allow-dev-code', effect: 'allow', actions: ['code.*'], roles: ['developer'], environments: ['development'] },
  { id: 'deny-prod-write', effect: 'deny', actions: ['code.write'], environments: ['production'], priority: 100 },
];

const pureStarted = performance.now();
for (let i = 0; i < iterations; i++) evaluatePolicy(request, rules, 'enforce');
const pureMs = performance.now() - pureStarted;

const receiptIterations = Math.min(iterations, 5_000);
const engine = new AgenticPolicyEngine({ mode: 'enforce', rules });
const receiptStarted = performance.now();
for (let i = 0; i < receiptIterations; i++) engine.evaluate({ ...request, requestId: `bench-${i}` });
const receiptMs = performance.now() - receiptStarted;

const report = {
  schema: 'ruflo.policy-benchmark/v1',
  pure: {
    iterations,
    durationMs: Number(pureMs.toFixed(3)),
    opsPerSecond: Math.round(iterations / (pureMs / 1_000)),
    microsPerDecision: Number(((pureMs * 1_000) / iterations).toFixed(3)),
  },
  withReceipts: {
    iterations: receiptIterations,
    durationMs: Number(receiptMs.toFixed(3)),
    opsPerSecond: Math.round(receiptIterations / (receiptMs / 1_000)),
    microsPerDecision: Number(((receiptMs * 1_000) / receiptIterations).toFixed(3)),
    ledgerValid: engine.verifyLedger().valid,
  },
};

console.log(JSON.stringify(report, null, 2));
if (!report.withReceipts.ledgerValid) process.exitCode = 1;

import { generateKeyPairSync, sign } from 'node:crypto';
import { performance } from 'node:perf_hooks';
import {
  canonicalProductPlaneBytes,
  canonicalizeProductPlane,
  verifySignedProductActionEnvelope,
} from '../dist/policy/product-plane.js';

const digest = `sha256:${'a'.repeat(64)}`;
const envelope = {
  schemaVersion: 'cognitum.action.v1',
  eventId: 'benchmark-event',
  issuer: 'ruflo.policy',
  audience: 'meta-llm',
  subject: { namespace: 'firebase-subject', id: 'benchmark-user' },
  actor: { namespace: 'workload', id: 'spiffe://cognitum.example/agent/benchmark' },
  tenantRef: { namespace: 'meta-llm-account', id: 'benchmark-tenant' },
  action: 'inference.invoke',
  resourceRefs: ['meta-llm://models/cognitum-auto'],
  requestDigest: digest,
  idempotencyKey: 'benchmark-idempotency',
  correlationId: 'benchmark-correlation',
  authoritativeSource: {
    authority: 'meta-llm',
    tenantRef: { namespace: 'meta-llm-account', id: 'benchmark-tenant' },
    sourceType: 'meta-llm/inference',
    sourceId: 'benchmark-request',
    sourceVersion: '1',
    sourceDigest: digest,
  },
  sequence: '1',
  policyReceiptId: 'benchmark-policy-receipt',
  capabilityId: 'benchmark-capability',
  occurredAt: '2026-07-28T12:00:00.000Z',
  expiresAt: '2026-07-28T12:05:00.000Z',
  privacyClass: 'P1',
};

const keys = generateKeyPairSync('ed25519');
const signed = {
  envelope,
  algorithm: 'Ed25519',
  keyId: 'benchmark-key',
  signature: sign(null, canonicalProductPlaneBytes(envelope), keys.privateKey).toString('base64url'),
};
const options = {
  expectedAudience: 'meta-llm',
  expectedTenantRef: { namespace: 'meta-llm-account', id: 'benchmark-tenant' },
  now: () => Date.parse('2026-07-28T12:01:00.000Z'),
  maxAgeMs: 5 * 60_000,
  resolveKey: () => keys.publicKey,
  replayStore: { reserve: () => 'reserved' },
  policyVerifier: () => ({ allowed: true }),
  capabilityVerifier: () => ({ allowed: true }),
};

function percentile(values, fraction) {
  const ordered = [...values].sort((left, right) => left - right);
  return ordered[Math.min(ordered.length - 1, Math.floor(ordered.length * fraction))];
}

async function measure(name, batches, iterations, operation) {
  const samples = [];
  for (let batch = 0; batch < batches; batch++) {
    const started = performance.now();
    for (let iteration = 0; iteration < iterations; iteration++) await operation();
    samples.push(((performance.now() - started) * 1000) / iterations);
  }
  return {
    name,
    batches,
    iterationsPerBatch: iterations,
    latencyMicroseconds: {
      p50: percentile(samples, 0.50),
      p95: percentile(samples, 0.95),
      p99: percentile(samples, 0.99),
    },
    throughputPerSecond: 1_000_000 / percentile(samples, 0.50),
  };
}

const results = [
  await measure('canonicalize-product-envelope', 20, 10_000, () => {
    canonicalizeProductPlane(envelope);
  }),
  await measure('verify-ed25519-product-envelope', 20, 500, async () => {
    const result = await verifySignedProductActionEnvelope(signed, options);
    if (!result.ok) throw new Error(`benchmark verification failed: ${result.code}`);
  }),
];

console.log(JSON.stringify({
  schema: 'cognitum.product-plane-benchmark/v1',
  node: process.version,
  platform: `${process.platform}-${process.arch}`,
  canonicalBytes: canonicalProductPlaneBytes(envelope).length,
  results,
}, null, 2));

/**
 * Release and CI guard for the OAuth surface consumed by `ruflo auth`.
 * This deliberately imports the built package entry point, rather than
 * source files, so a stale or incomplete npm artifact cannot pass.
 */
const security = await import('../dist/index.js');

const requiredFunctions = [
  'authorizeUrl',
  'exchangeCode',
  'refreshToken',
  'exchangeManualCode',
  'generatePkce',
  'openBrowser',
  'createKeychainAdapter',
];
const requiredClasses = ['CallbackServer', 'OAuthError'];

const missing = [
  ...requiredFunctions.filter((name) => typeof security[name] !== 'function'),
  ...requiredClasses.filter((name) => typeof security[name] !== 'function'),
  ...(typeof security.OOB_REDIRECT_URI === 'string' ? [] : ['OOB_REDIRECT_URI']),
];

if (missing.length > 0) {
  throw new Error(`@claude-flow/security is missing required OAuth exports: ${missing.join(', ')}`);
}

console.log(`OAuth export surface verified (${requiredFunctions.length + requiredClasses.length + 1} exports)`);

/**
 * CVE Remediation Tracking
 *
 * This file documents all security vulnerabilities addressed in the V3 security module
 * and provides programmatic tracking of remediation status.
 *
 * Updated: 2026-06-30 — Phase 1 (ADR-165) — closed all critical advisories in both
 * root and v3 workspaces via dependency upgrades and npm overrides.
 *
 * @module v3/security/CVE-REMEDIATION
 */

export interface CVEEntry {
  id: string;
  title: string;
  severity: 'critical' | 'high' | 'medium' | 'low';
  description: string;
  affectedFiles: string[];
  remediationFile: string;
  remediationStatus: 'fixed' | 'in_progress' | 'pending';
