const CALLER_AUTH_ENV = 'CLAUDE_FLOW_MCP_CALLER_AUTH';

/** Off by default — see the file header re: key distribution being out of scope pending a follow-on ADR. Only the literal `'true'` enables enforcement. */
export function isMcpCallerAuthEnabled(): boolean {
  return process.env[CALLER_AUTH_ENV] === 'true';
}

/**
 * MCP Tool Composition Inspector — ADR-320 (this ADR; ruvnet/ruflo dream-cycle
 * proposal, arXiv:2606.27027 "ShareLock").
 *
 * The attack: an adversary registers N seemingly-benign MCP tools whose
 * individual descriptions look fine in isolation, but whose CONCATENATION
 * (or pairwise overlap) forms an injection payload targeting a downstream
 * agent — a Shamir-secret-sharing-style split across tool descriptions.
 * Per-tool inspection misses this because each fragment sits under any
 * single-tool detection threshold.
 *
 * Relationship to prior art in this repo
 * ---------------------------------------
 * A CLI-only v1 of this idea already shipped directly to `main`
 * (dream-cycle #2783, commits 381b7ebcc/581cd2bf3) as
 * `v3/@claude-flow/cli/src/security/mcp-composition-inspector.ts` — an
 * on-demand `ruflo security composition-scan` command using exact
 * common-substring matching plus an injection-phrase catalog and
 * typosquat check. That module's own header explicitly scopes itself as
 * "a bounded engineering fix rather than an ADR-scope subsystem" and lists
 * "Future v2: SimHash + LSH for scale" as deliberately deferred. THIS
 * module is that v2: a reusable `@claude-flow/security` library primitive
 * (not a CLI-only tool) built around a real SimHash fingerprint, so it can
 * be called from a pre-task/pre-tool-use hook before a multi-tool chain
 * executes, per this ADR's implementation target. It does not replace or
 * import the CLI v1 — the two are independent, complementary detectors
 * (exact-substring vs. hashed-shingle-overlap) that a caller may run
 * together.
 *
 * Detection method (deterministic, no LLM call)
 * -----------------------------------------------
 * 1. Each tool description is normalized and split into overlapping
 *    word-shingles (default: 5-word windows). Shingling — rather than
 *    whole-description comparison — is what lets us find a SMALL embedded
 *    fragment inside an otherwise unrelated, benign description.
 * 2. Each tool gets a 64-bit SimHash fingerprint: every shingle is hashed
 *    (FNV-1a, 64-bit) and the fingerprint bits are set by majority vote
 *    across all of a tool's shingle hashes. Two tools whose descriptions
 *    share enough content have a SMALL Hamming distance between
 *    fingerprints — this is the O(1)-per-pair coarse filter that avoids an
 *    LLM call and stays cheap even at hundreds of registered tools (fast
 *    64-bit XOR + popcount per pair).
 * 3. An inverted shingle-hash index (hash -> set of tool indices) is built
 *    once, in O(total shingles). For each pair flagged by the SimHash
 *    filter (or found in the index) the SAME index is used to compute the
 *    actual overlapping shingle text — this is what makes the finding
 *    reportable (the SimHash score alone can't tell an operator *what*
 *    matched).
 * 4. A fragment's "population" (how many distinct tools carry it) caps
 *    false positives: shared shingles that appear in more than
 *    `maxFragmentPopulation` (default 3) tools are template language
 *    (e.g. every ruflo `memory_*` tool's boilerplate), not an attack —
 *    Shamir-split attacks concentrate a fragment in a small conspiracy of
 *    2-3 tools. Same population-cap idea as the CLI v1, reimplemented here
 *    against the hash index instead of raw substrings.
 *
 * This is a heuristic detector, not a security boundary: it reports
 * SUSPECTS. Default action is warn + log; blocking is opt-in via
 * `CLAUDE_FLOW_MCP_COMPOSITION_BLOCK=1` (see {@link evaluateToolComposition}).
 *
 * @module @claude-flow/security/mcp-composition-inspector
 */

// ============================================================================
// Types
// ============================================================================

export interface McpToolDescriptor {
  name: string;
  description: string;
}

export interface CompositionInspectorOptions {
  /** Words per shingle window. Default 5. */
  shingleSize?: number;
  /** SimHash similarity (1 - Hamming/64) at/above which a pair is a candidate. Default 0.6. */
  simhashThreshold?: number;
  /** Fraction of a tool's shingles shared with a peer (low-population only) at/above which a pair is flagged. Default 0.25. */
  fragmentOverlapThreshold?: number;
  /** Max number of distinct tools a shingle may appear in before it's treated as template language, not an attack fragment. Default 3. */
  maxFragmentPopulation?: number;
  /** Minimum character length for a shingle to be indexed (filters trivial/common short phrases). Default 12. */
  minShingleChars?: number;
  /** Max sample shared fragments recorded per finding (display only). Default 5. */
  maxSampleFragments?: number;
}

export interface CompositionFinding {
  toolA: string;
  toolB: string;
  /** 1 - (Hamming distance / 64) between the two tools' SimHash fingerprints. */
  simhashSimilarity: number;
  /** sharedLowPopulationShingles / min(shingleCount(A), shingleCount(B)). */
  fragmentOverlapScore: number;
  /** Sample of the actual shared shingle text driving the finding (truncated). */
  sharedFragments: string[];
  /** Max population (distinct tools) observed among the shared shingles that triggered this finding. */
  fragmentPopulation: number;
  reason: string;
}

export interface CompositionInspectionStats {
  toolsScanned: number;
  pairsCompared: number;
  shinglesIndexed: number;
  /** Pairs whose SimHash similarity alone crossed simhashThreshold (diagnostic — includes pairs later excluded for having no low-population shared shingle). */
  candidatePairsFromSimhash: number;
}

export interface CompositionInspectionResult {
  findings: CompositionFinding[];
  stats: CompositionInspectionStats;
}

export interface CompositionGuardResult {
  result: CompositionInspectionResult;
  action: 'none' | 'warn' | 'block';
  blocked: boolean;
  message?: string;
}

// ============================================================================
// SimHash primitives (plain TS, no dependency)
// ============================================================================

const FNV_OFFSET_BASIS_64 = 0xcbf29ce484222325n;
const FNV_PRIME_64 = 0x100000001b3n;
const MASK_64 = (1n << 64n) - 1n;

/** FNV-1a, 64-bit. Deterministic, dependency-free, good avalanche for short strings. */
export function fnv1a64(input: string): bigint {
  let hash = FNV_OFFSET_BASIS_64;
  for (let i = 0; i < input.length; i++) {
    hash ^= BigInt(input.charCodeAt(i));
    hash = (hash * FNV_PRIME_64) & MASK_64;
  }
  return hash;
}

/**
 * Classic SimHash: bit-vote a 64-bit fingerprint across a list of token
 * hashes. Near-duplicate token sets (even with some fragments differing)
 * produce fingerprints with a small Hamming distance.
 */
export function simhash64(shingles: readonly string[]): bigint {
  if (shingles.length === 0) return 0n;
  const bitVotes = new Array<number>(64).fill(0);
  for (const shingle of shingles) {
    const h = fnv1a64(shingle);
    for (let bit = 0; bit < 64; bit++) {
      const set = (h >> BigInt(bit)) & 1n;
      bitVotes[bit] += set === 1n ? 1 : -1;
    }
  }
  let fingerprint = 0n;
  for (let bit = 0; bit < 64; bit++) {
    if (bitVotes[bit] > 0) fingerprint |= 1n << BigInt(bit);
  }
  return fingerprint;
}

/** Hamming distance between two 64-bit fingerprints (0..64). */
export function hammingDistance64(a: bigint, b: bigint): number {
  let x = (a ^ b) & MASK_64;
  let count = 0;
  while (x > 0n) {
    count += Number(x & 1n);
    x >>= 1n;
  }
  return count;
}

// ============================================================================
// Shingling
// ============================================================================

function normalize(text: string): string {
  return text.toLowerCase().replace(/\s+/g, ' ').trim();
}

/** Overlapping word-shingles of `k` words each. Falls back to the whole (short) text as a single shingle. */
function wordShingles(text: string, k: number): string[] {
  const words = normalize(text).split(' ').filter(Boolean);
  if (words.length === 0) return [];
  if (words.length < k) return [words.join(' ')];
  const shingles: string[] = [];
  for (let i = 0; i + k <= words.length; i++) {
    shingles.push(words.slice(i, i + k).join(' '));
  }
  return shingles;
}

// ============================================================================
// Inspection
// ============================================================================

interface IndexedTool {
  idx: number;
  name: string;
  shingles: string[];
  hashKeys: Set<string>;
  fingerprint: bigint;
}

export function inspectToolComposition(
  tools: readonly McpToolDescriptor[],
  options: CompositionInspectorOptions = {},
): CompositionInspectionResult {
  const shingleSize = options.shingleSize ?? 5;
  const simhashThreshold = options.simhashThreshold ?? 0.6;
  const fragmentOverlapThreshold = options.fragmentOverlapThreshold ?? 0.25;
  const maxFragmentPopulation = options.maxFragmentPopulation ?? 3;
  const minShingleChars = options.minShingleChars ?? 12;
  const maxSampleFragments = options.maxSampleFragments ?? 5;

  const indexed: IndexedTool[] = tools.map((t, idx) => {
    const shingles = wordShingles(t.description, shingleSize).filter((s) => s.length >= minShingleChars);
    const hashKeys = new Set(shingles.map((s) => fnv1a64(s).toString(36)));
    return {
      idx,
      name: t.name,
      shingles,
      hashKeys,
      fingerprint: simhash64(shingles),
    };
  });

  // Inverted index: shingle-hash -> {tools that carry it, sample text}.
  const shingleToTools = new Map<string, Set<number>>();
  const shingleSampleText = new Map<string, string>();
  for (const t of indexed) {
    for (const shingle of t.shingles) {
      const key = fnv1a64(shingle).toString(36);
      const set = shingleToTools.get(key) ?? new Set<number>();
      set.add(t.idx);
      shingleToTools.set(key, set);
      if (!shingleSampleText.has(key)) shingleSampleText.set(key, shingle);
    }
  }

  const findings: CompositionFinding[] = [];
  const stats: CompositionInspectionStats = {
    toolsScanned: tools.length,
    pairsCompared: 0,
    shinglesIndexed: shingleToTools.size,
    candidatePairsFromSimhash: 0,
  };

  for (let i = 0; i < indexed.length; i++) {
    for (let j = i + 1; j < indexed.length; j++) {
      stats.pairsCompared++;
      const a = indexed[i];
      const b = indexed[j];

      const hamming = hammingDistance64(a.fingerprint, b.fingerprint);
      const simhashSimilarity = a.shingles.length > 0 && b.shingles.length > 0 ? 1 - hamming / 64 : 0;
      if (simhashSimilarity >= simhashThreshold) stats.candidatePairsFromSimhash++;

      // Low-population shared shingles between this pair, via the inverted index.
      let sharedCount = 0;
      let maxPopulationSeen = 0;
      const sample: string[] = [];
      for (const key of a.hashKeys) {
        if (!b.hashKeys.has(key)) continue;
        const population = shingleToTools.get(key)?.size ?? 0;
        if (population > maxFragmentPopulation) continue; // template language, not an attack signature
        sharedCount++;
        maxPopulationSeen = Math.max(maxPopulationSeen, population);
        if (sample.length < maxSampleFragments) {
          const text = shingleSampleText.get(key);
          if (text) sample.push(text);
        }
      }

      const minShingleCount = Math.max(1, Math.min(a.shingles.length, b.shingles.length));
      const fragmentOverlapScore = sharedCount / minShingleCount;

      const flagBySimhash = simhashSimilarity >= simhashThreshold && sharedCount > 0;
      const flagByFragment = fragmentOverlapScore >= fragmentOverlapThreshold && sharedCount > 0;
      if (!flagBySimhash && !flagByFragment) continue;

      findings.push({
        toolA: a.name,
        toolB: b.name,
        simhashSimilarity: Number(simhashSimilarity.toFixed(3)),
        fragmentOverlapScore: Number(fragmentOverlapScore.toFixed(3)),
        sharedFragments: sample,
        fragmentPopulation: maxPopulationSeen,
        reason: flagBySimhash
          ? `SimHash similarity ${simhashSimilarity.toFixed(2)} (Hamming distance ${hamming}/64) with ${sharedCount} low-population shared shingle(s) (population <= ${maxFragmentPopulation}) — possible cross-tool instruction fragment`
          : `Fragment overlap ${fragmentOverlapScore.toFixed(2)} (${sharedCount}/${minShingleCount} shingles shared, population <= ${maxFragmentPopulation}) — possible Shamir-split instruction fragment`,
      });
    }
  }

  return { findings, stats };
}

// ============================================================================
// Guard: env-var-gated warn/block decision
// ============================================================================

const COMPOSITION_BLOCK_ENV = 'CLAUDE_FLOW_MCP_COMPOSITION_BLOCK';

/** Reads `CLAUDE_FLOW_MCP_COMPOSITION_BLOCK` fresh on every call. '1' or 'true' (case-insensitive) enables blocking; unset/anything else keeps the default warn+log posture. */
export function isCompositionBlockEnabled(): boolean {
  const raw = process.env[COMPOSITION_BLOCK_ENV];
  return raw === '1' || raw?.toLowerCase() === 'true';
}

/**
 * Runs {@link inspectToolComposition} and applies the ADR-320 default
 * posture: warn + log (via `console.warn`) unless
 * `CLAUDE_FLOW_MCP_COMPOSITION_BLOCK=1`, in which case the chain is marked
 * `blocked: true` — the caller (the pre-task hook / MCP dispatcher) decides
 * what "blocked" means operationally; this function does not throw or abort
 * anything itself.
 */
export function evaluateToolComposition(
  tools: readonly McpToolDescriptor[],
  options: CompositionInspectorOptions = {},
): CompositionGuardResult {
  const result = inspectToolComposition(tools, options);
  if (result.findings.length === 0) {
    return { result, action: 'none', blocked: false };
  }

  const summary =
    `MCP Composition Inspector: ${result.findings.length} suspicious cross-tool fragment(s) ` +
    `across ${result.stats.toolsScanned} tools (${result.stats.pairsCompared} pairs compared)`;

  if (isCompositionBlockEnabled()) {
    const message = `${summary} — blocking chain (${COMPOSITION_BLOCK_ENV}=1)`;
    console.warn(`[mcp-composition-inspector] ${message}`);
    for (const f of result.findings) {
      console.warn(`  - ${f.toolA} <-> ${f.toolB}: ${f.reason}`);
    }
    return { result, action: 'block', blocked: true, message };
  }

  console.warn(`[mcp-composition-inspector] ${summary}`);
  for (const f of result.findings) {
    console.warn(`  - ${f.toolA} <-> ${f.toolB}: ${f.reason}`);
  }
  return { result, action: 'warn', blocked: false, message: summary };
}

/**
 * Opens the system default browser for the `ruflo auth login` flow. A
 * TypeScript port of meta-proxy's `src/oauth/browser.rs`.
 *
 * Deliberately does NOT go through `SafeExecutor.execute()`: `SafeExecutor`'s
 * blocked-argument patterns (`safe-executor.ts`'s `DEFAULT_BLOCKED_PATTERNS`)
 * include a bare `&`, which is meant to catch shell-metacharacter injection in
 * command-line-style arguments — but it also appears in every real OAuth
 * authorize URL's query string (`?a=1&b=2&...`), so passing one through would
 * false-positive-reject on every real invocation. That blocklist is the wrong
 * tool for a URL argument: with `shell: false` (used here, same as
 * `SafeExecutor`), a single argv element containing `&` is inert — there's no
 * shell to interpret it. The actual safety property that matters is "the URL
 * was constructed by us from validated components, never from raw external
 * input" (this module's `authorizeUrl()` in `client.ts` is the only caller),
 * which `assertSafeUrl` below checks directly instead.
 *
 * @module v3/security/oauth/browser
 */

import { execFile } from 'node:child_process';

/** Throws if `url` isn't a well-formed https/http URL — the one check that matters here. */
function assertSafeUrl(url: string): void {
  const parsed = new URL(url); // throws on malformed input
  if (parsed.protocol !== 'https:' && parsed.protocol !== 'http:') {
    throw new Error(`refusing to open non-http(s) URL scheme: ${parsed.protocol}`);
  }
}

/**
 * Attempts to open `url` in the system default browser. Resolves whether or
 * not a browser window actually appeared — this cannot be confirmed in
 * general, which is why the caller always also prints the URL as a fallback.
 */
export function openBrowser(url: string): Promise<void> {
  assertSafeUrl(url);

  const { cmd, args } = browserCommand(url);

  return new Promise((resolve) => {
    execFile(cmd, args, { shell: false, windowsHide: true }, () => resolve());
  });
}

/** Pure command selection, exported for platform regression tests. */
export function browserCommand(url: string, platform: NodeJS.Platform = process.platform): { cmd: string; args: string[] } {
  assertSafeUrl(url);
  if (platform === 'darwin') {
    return { cmd: 'open', args: [url] };
  } else if (platform === 'win32') {
    // cmd.exe treats OAuth query-string `&` separators as command operators,
    // truncating the URL before client_id. Use the URL handler without a shell.
    return { cmd: 'rundll32.exe', args: ['url.dll,FileProtocolHandler', url] };
  } else {
    return { cmd: 'xdg-open', args: [url] };
  }
}

/**
 * Ephemeral-port localhost callback server for the browser-based OAuth flow
 * (ADR-306). A minimal single-request HTTP server — deliberately not a full
 * framework for one GET route that lives for one request and then shuts
 * down. A TypeScript port of meta-proxy's `src/oauth/callback_server.rs`.
 *
 * @module v3/security/oauth/callback-server
 */

import { createServer, type Server } from 'node:http';
import type { AddressInfo } from 'node:net';

export interface CallbackResult {
  code: string | null;
  state: string | null;
  error: string | null;
}

const SUCCESS_PAGE = `<html>
<body style="background:#0a0a0a; color:#f5f5f5; font-family:sans-serif;
    display:flex; align-items:center; justify-content:center;
    height:100vh; margin:0;">
    <div style="text-align:center;">
    <h1>&#10003; ruflo login successful</h1>
    <p>You can close this tab and return to your terminal.</p>
    </div>
</body>
</html>`;

const DEFAULT_TIMEOUT_MS = 5 * 60 * 1000; // 5 minutes, matches meta-proxy's CALLBACK_TIMEOUT

export class CallbackTimeoutError extends Error {
  constructor() {
    super('timed out waiting for OAuth callback');
    this.name = 'CallbackTimeoutError';
  }
}

export class CallbackServer {
  private constructor(
    private readonly server: Server,
    public readonly redirectUri: string,
    public readonly port: number,
  ) {}

  /**
   * Binds `127.0.0.1:0` (OS-assigned ephemeral port) and returns the server
   * plus the exact `redirect_uri` to send in the authorize request — must be
   * the `http://127.0.0.1:<port>/oauth/callback` shape identity's
   * `validate_redirect_uri` accepts.
   */
  static async bind(): Promise<CallbackServer> {
    return new Promise((resolve, reject) => {
      const server = createServer();
      server.once('error', reject);
      server.listen(0, '127.0.0.1', () => {
        server.removeListener('error', reject);
        const addr = server.address() as AddressInfo;
        const redirectUri = `http://127.0.0.1:${addr.port}/oauth/callback`;
        resolve(new CallbackServer(server, redirectUri, addr.port));
      });
    });
  }

  /**
   * Waits for exactly one `GET /oauth/callback?...` request, replies with the
   * browser success page, closes the server, and returns the parsed query
   * parameters. Times out after `waitForMs` so a login attempt the user
   * abandons in the browser doesn't hang the CLI forever.
   */
  async awaitCallback(waitForMs = DEFAULT_TIMEOUT_MS): Promise<CallbackResult> {
    return new Promise((resolve, reject) => {
      const timer = setTimeout(() => {
        this.server.close();
        reject(new CallbackTimeoutError());
      }, waitForMs);

      this.server.once('request', (req, res) => {
        clearTimeout(timer);
        const url = new URL(req.url ?? '/oauth/callback', 'http://127.0.0.1');
        const result: CallbackResult = {
          code: url.searchParams.get('code'),
          state: url.searchParams.get('state'),
          error: url.searchParams.get('error'),
        };
        res.writeHead(200, {
          'content-type': 'text/html; charset=utf-8',
          connection: 'close',
        });
        res.end(SUCCESS_PAGE, () => {
          this.server.close();
          resolve(result);
        });
      });
    });
  }
}

/**
 * HTTP client for `auth.cognitum.one`'s OAuth surface (ADR-306): authorize
 * URL construction, `POST /oauth/token` (`authorization_code` and
 * `refresh_token` grants), and `POST /v1/oauth/code-exchange` (OOB fallback).
 *
 * A TypeScript port of meta-proxy's `src/oauth/client.rs`
 * (cognitum-one/meta-proxy) — same base URL, same endpoints, same
 * form/query parameter names, confirmed live 2026-07-16 (a real
 * `GET /oauth/authorize?...&client_id=meta-proxy&redirect_uri=<ruflo-controlled
 * loopback>` returns a working consent page, not a redirect_uri-mismatch
 * error — so this client reuses meta-proxy's registered `client_id` rather
 * than requiring a new one).
 *
 * Deliberately NOT `api.cognitum.one/v1/auth/*` — that's what ruflo's own
 * checked-in OpenAPI spec (v3/docs/api/cognitum-v1.openapi.yaml, ADR-308)
 * describes, but it does not match what the real identity server serves.
 * This client targets the proven, live surface instead.
 *
 * @module v3/security/oauth/client
 */

export const CLIENT_ID = 'meta-proxy';
export const SCOPE = 'inference';
/** RFC 8252 out-of-band sentinel — the OOB/manual-paste flow's `redirect_uri`. */
export const OOB_REDIRECT_URI = 'urn:ietf:wg:oauth:2.0:oob';

function authBaseUrl(): string {
  const override = process.env.COGNITUM_AUTH_URL;
  return override && override.trim() ? override : 'https://auth.cognitum.one';
}

export interface TokenResponse {
  access_token: string;
  token_type: string;
  account_email?: string;
  refresh_token?: string;
  expires_in?: number;
}

interface OAuthErrorBody {
  error: string;
  error_description: string;
}

export class OAuthError extends Error {
  constructor(
    message: string,
    public readonly code: 'network' | 'protocol' | 'unexpected_shape',
    public readonly oauthError?: string,
    public readonly oauthDescription?: string,
  ) {
    super(message);
    this.name = 'OAuthError';
  }
}

/** Builds the `/oauth/authorize` URL for the standard loopback-redirect flow. */
export function authorizeUrl(redirectUri: string, state: string, codeChallenge: string): string {
  const url = new URL(`${authBaseUrl()}/oauth/authorize`);
  url.searchParams.set('response_type', 'code');
  url.searchParams.set('client_id', CLIENT_ID);
  url.searchParams.set('redirect_uri', redirectUri);
  url.searchParams.set('scope', SCOPE);
  url.searchParams.set('state', state);
  url.searchParams.set('code_challenge', codeChallenge);
  url.searchParams.set('code_challenge_method', 'S256');
  return url.toString();
}

async function parseTokenResponse(resp: Response): Promise<TokenResponse> {
  if (resp.ok) {
    try {
      return (await resp.json()) as TokenResponse;
    } catch {
      throw new OAuthError('unexpected response shape from the server', 'unexpected_shape');
    }
  }
  try {
    const body = (await resp.json()) as OAuthErrorBody;
    throw new OAuthError(
      `oauth error: ${body.error} — ${body.error_description}`,
      'protocol',
      body.error,
      body.error_description,
    );
  } catch (e) {
    if (e instanceof OAuthError) throw e;
    throw new OAuthError('unexpected response shape from the server', 'unexpected_shape');
  }
}

async function postForm(path: string, form: Record<string, string>, base = authBaseUrl()): Promise<TokenResponse> {
  let resp: Response;
  try {
    resp = await fetch(`${base}${path}`, {
      method: 'POST',
      headers: { 'content-type': 'application/x-www-form-urlencoded' },
      body: new URLSearchParams(form).toString(),
    });
  } catch (e) {
    throw new OAuthError(`network error: ${e instanceof Error ? e.message : String(e)}`, 'network');
  }
  return parseTokenResponse(resp);
}

/** `POST /oauth/token` with `grant_type=authorization_code`. */
export async function exchangeCode(
  code: string,
  codeVerifier: string,
  redirectUri: string,
  base = authBaseUrl(),
): Promise<TokenResponse> {
  return postForm(
    '/oauth/token',
    { grant_type: 'authorization_code', code, code_verifier: codeVerifier, client_id: CLIENT_ID, redirect_uri: redirectUri },
    base,
  );
}

/**
 * `POST /oauth/token` with `grant_type=refresh_token`. identity rotates
 * refresh tokens with reuse detection: presenting a refresh token returns a
 * NEW refresh token and revokes the old one, and re-presenting a spent one
 * revokes the whole session family. Callers MUST persist the returned
 * `refresh_token` atomically before using the new access token, and must
 * never retry a failed refresh with the same token.
 */
export async function refreshToken(refreshTokenValue: string, base = authBaseUrl()): Promise<TokenResponse> {
  return postForm('/oauth/token', { grant_type: 'refresh_token', refresh_token: refreshTokenValue, client_id: CLIENT_ID }, base);
}

/**
 * `POST /v1/oauth/code-exchange` — the OOB manual-entry fallback for
 * headless/SSH/container environments where no browser round-trip to
 * `127.0.0.1` is reachable.
 */
export async function exchangeManualCode(
  code: string,
  codeVerifier: string,
  base = authBaseUrl(),
): Promise<TokenResponse> {
  let resp: Response;
  try {
    resp = await fetch(`${base}/v1/oauth/code-exchange`, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ code, code_verifier: codeVerifier, client_id: CLIENT_ID }),
    });
  } catch (e) {
    throw new OAuthError(`network error: ${e instanceof Error ? e.message : String(e)}`, 'network');
  }
  return parseTokenResponse(resp);
}

/**
 * OAuth 2.0 + PKCE (RFC 7636) client-side generation (ADR-306).
 *
 * A TypeScript port of meta-proxy's `src/oauth/pkce.rs` (cognitum-one/meta-proxy,
 * itself ported from `dashboard/apps/cli/src/pkce.rs`) so a verifier generated
 * here validates against the same `services/identity` authorization server
 * meta-proxy already talks to successfully — same byte lengths, same encoding,
 * same hash. Intentionally duplicated rather than imported from
 * `@claude-flow/mcp/src/oauth.ts` (a different, unrelated OAuth client in this
 * monorepo) — ADR-306 assigns PKCE ownership to this package specifically.
 *
 * @module v3/security/oauth/pkce
 */

import { randomBytes, createHash } from 'crypto';

export interface PkceRequest {
  state: string;
  codeVerifier: string;
  codeChallenge: string;
}

/**
 * 32 random bytes, base64url-encoded (no padding) — comfortably within RFC
 * 7636's 43-128 character verifier length requirement (32 bytes -> 43 chars).
 * Matches the Rust port's `random_url_safe_token(32)` exactly.
 */
function randomUrlSafeToken(byteLen: number): string {
  return randomBytes(byteLen).toString('base64url');
}

export function challengeFromVerifier(verifier: string): string {
  return createHash('sha256').update(verifier).digest('base64url');
}

/**
 * Generates a fresh `state` + PKCE verifier/challenge pair for one login
 * attempt.
 */
export function generate(): PkceRequest {
  const state = randomUrlSafeToken(32);
  const codeVerifier = randomUrlSafeToken(32);
  const codeChallenge = challengeFromVerifier(codeVerifier);
  return { state, codeVerifier, codeChallenge };
}

/**
 * Password Hasher - CVE-2 Remediation
 *
 * Fixes weak password hashing by replacing SHA-256 with hardcoded salt
 * with bcrypt using 12 rounds (configurable).
 *
 * Security Properties:
 * - bcrypt with adaptive cost factor (12 rounds)
 * - Automatic salt generation per password
 * - Timing-safe comparison
 * - Minimum password length enforcement
 *
 * @module v3/security/password-hasher
 */

// #1608 — switched from `bcrypt` to `bcryptjs` to drop the
// `@mapbox/node-pre-gyp → tar <=7.5.10` transitive chain that pulled in
// 6 HIGH-severity CVEs (GHSA-34x7-hfp2-rc4v, GHSA-8qq5-rm4j-mr97, etc.).
// `bcryptjs` is a pure-JS implementation that produces the same `$2a$` /
// `$2b$` hash format and exposes the same `hash()` / `compare()` API
// surface this module uses, so the swap is transparent to callers and to
// any persisted hashes.
import * as bcrypt from 'bcryptjs';

export interface PasswordHasherConfig {
  /**
   * Number of bcrypt rounds (cost factor).
   * Default: 12 (recommended minimum for production)
   * Each increment doubles the computation time.
   */
  rounds?: number;

  /**
   * Minimum password length.
   * Default: 8 characters
   */
  minLength?: number;

  /**
   * Maximum password length.
   * Default: 128 characters (bcrypt limit is 72 bytes)
   */
  maxLength?: number;

  /**
   * Require at least one uppercase letter.
   * Default: true
   */
  requireUppercase?: boolean;

  /**
   * Require at least one lowercase letter.
   * Default: true
   */
  requireLowercase?: boolean;

  /**
   * Require at least one digit.
   * Default: true
   */
  requireDigit?: boolean;

  /**
   * Require at least one special character.
   * Default: false
   */
  requireSpecial?: boolean;
}

export interface PasswordValidationResult {
  isValid: boolean;
  errors: string[];
}

export class PasswordHashError extends Error {
  constructor(
    message: string,
    public readonly code: string,
  ) {
    super(message);
    this.name = 'PasswordHashError';
  }
}

/**
 * Secure password hasher using bcrypt.
 *
 * This class replaces the vulnerable SHA-256 + hardcoded salt implementation
 * with industry-standard bcrypt hashing.
 *
 * @example
 * ```typescript
 * const hasher = new PasswordHasher({ rounds: 12 });
 * const hash = await hasher.hash('securePassword123');
 * const isValid = await hasher.verify('securePassword123', hash);
 * ```
 */
export class PasswordHasher {
  private readonly config: Required<PasswordHasherConfig>;

  constructor(config: PasswordHasherConfig = {}) {
    this.config = {
      rounds: config.rounds ?? 12,
      minLength: config.minLength ?? 8,
      maxLength: config.maxLength ?? 128,
      requireUppercase: config.requireUppercase ?? true,
      requireLowercase: config.requireLowercase ?? true,
      requireDigit: config.requireDigit ?? true,
      requireSpecial: config.requireSpecial ?? false,
    };

    // Validate configuration
    if (this.config.rounds < 10 || this.config.rounds > 20) {
      throw new PasswordHashError(
        'Bcrypt rounds must be between 10 and 20 for security and performance balance',
        'INVALID_ROUNDS'
      );
    }

    if (this.config.minLength < 8) {
      throw new PasswordHashError(
        'Minimum password length must be at least 8 characters',
        'INVALID_MIN_LENGTH'
      );
    }
  }

  /**
   * Validates password against configured requirements.
   *
   * @param password - The password to validate
   * @returns Validation result with errors if any
   */
  validate(password: string): PasswordValidationResult {
    const errors: string[] = [];

    if (!password) {
      errors.push('Password is required');
      return { isValid: false, errors };
    }

    if (password.length < this.config.minLength) {
      errors.push(`Password must be at least ${this.config.minLength} characters`);
    }

    if (password.length > this.config.maxLength) {
      errors.push(`Password must not exceed ${this.config.maxLength} characters`);
    }

    if (this.config.requireUppercase && !/[A-Z]/.test(password)) {
      errors.push('Password must contain at least one uppercase letter');
    }

    if (this.config.requireLowercase && !/[a-z]/.test(password)) {
      errors.push('Password must contain at least one lowercase letter');
    }

    if (this.config.requireDigit && !/\d/.test(password)) {
      errors.push('Password must contain at least one digit');
    }

    if (this.config.requireSpecial && !/[!@#$%^&*()_+\-=\[\]{};':"\\|,.<>\/?]/.test(password)) {
      errors.push('Password must contain at least one special character');
    }

    return {
      isValid: errors.length === 0,
      errors,
    };
  }

  /**
   * Hashes a password using bcrypt.
   *
   * @param password - The plaintext password to hash
   * @returns The bcrypt hash
   * @throws PasswordHashError if password is invalid
   */
  async hash(password: string): Promise<string> {
    const validation = this.validate(password);

    if (!validation.isValid) {
      throw new PasswordHashError(
        validation.errors.join('; '),
        'VALIDATION_FAILED'
      );
    }

    try {
      // bcrypt automatically generates a random salt per hash
      return await bcrypt.hash(password, this.config.rounds);
    } catch (error) {
      throw new PasswordHashError(
        'Failed to hash password',
        'HASH_FAILED'
      );
    }
  }

  /**
   * Verifies a password against a bcrypt hash.
   * Uses timing-safe comparison internally.
   *
   * @param password - The plaintext password to verify
   * @param hash - The bcrypt hash to compare against
   * @returns True if password matches, false otherwise
   */
  async verify(password: string, hash: string): Promise<boolean> {
    if (!password || !hash) {
      return false;
    }

    // Validate hash format (bcrypt hashes start with $2a$, $2b$, or $2y$)
    if (!this.isValidBcryptHash(hash)) {
      return false;
    }

    try {
      // bcrypt.compare uses timing-safe comparison
      return await bcrypt.compare(password, hash);
    } catch (error) {
      // Return false on any error to prevent timing attacks
      return false;
    }
  }

  /**
   * Checks if a hash needs to be rehashed with updated parameters.
   * Useful for upgrading hash strength over time.
   *
   * @param hash - The bcrypt hash to check
   * @returns True if hash should be updated
   */
  needsRehash(hash: string): boolean {
    if (!this.isValidBcryptHash(hash)) {
      return true;
    }

    // Extract rounds from hash (format: $2b$XX$...)
    const match = hash.match(/^\$2[aby]\$(\d{2})\$/);
    if (!match) {
      return true;
    }

    const hashRounds = parseInt(match[1], 10);
    return hashRounds < this.config.rounds;
  }

  /**
   * Validates bcrypt hash format.
   *
   * @param hash - The hash to validate
   * @returns True if valid bcrypt hash format
   */
  private isValidBcryptHash(hash: string): boolean {
    // bcrypt hash format: $2a$XX$22charsSalt31charsHash
    // Total length: 60 characters
    return /^\$2[aby]\$\d{2}\$[./A-Za-z0-9]{53}$/.test(hash);
  }

  /**
   * Returns current configuration (without sensitive defaults).
   */
  getConfig(): Readonly<Omit<Required<PasswordHasherConfig>, never>> {
    return { ...this.config };
  }
}

/**
 * Factory function to create a production-ready password hasher.
 *
 * @param rounds - Bcrypt rounds (default: 12)
 * @returns Configured PasswordHasher instance
 */
export function createPasswordHasher(rounds = 12): PasswordHasher {
  return new PasswordHasher({ rounds });
}

/**
 * Path Validator - HIGH-2 Remediation
 *
 * Fixes path traversal vulnerabilities by:
 * - Validating all file paths against allowed prefixes
 * - Using path.resolve() for canonicalization
 * - Blocking traversal patterns (../, etc.)
 * - Enforcing path length limits
 *
 * Security Properties:
 * - Path canonicalization
 * - Prefix validation
 * - Symlink resolution (optional)
 * - Traversal pattern detection
 *
 * Canonicalization is symmetric: a candidate is only ever compared against
 * prefixes held in the same form it was resolved in. Canonicalizing one side
 * and not the other silently denies everything under a symlinked prefix
 * (async) or silently accepts an escape through one (sync).
 *
 * @module v3/security/path-validator
 */

import * as path from 'path';
import * as fs from 'fs/promises';
import { realpathSync } from 'fs';

export interface PathValidatorConfig {
  /**
   * Allowed directory prefixes.
   * Paths must start with one of these after resolution.
   */
  allowedPrefixes: string[];

  /**
   * Blocked file extensions.
   * Files with these extensions are rejected.
   */
  blockedExtensions?: string[];

  /**
   * Blocked file names.
   * Files matching these names are rejected.
   */
  blockedNames?: string[];

  /**
   * Maximum path length.
   * Default: 4096 characters
   */
  maxPathLength?: number;

  /**
   * Whether to resolve symlinks.
   * Default: true
   */
  resolveSymlinks?: boolean;

  /**
   * Whether to allow paths that don't exist.
   * Default: true (for write operations)
   */
  allowNonExistent?: boolean;

  /**
   * Whether to allow hidden files/directories.
   * Default: false
   */
  allowHidden?: boolean;
}

export interface PathValidationResult {
  isValid: boolean;
  resolvedPath: string;
  relativePath: string;
  matchedPrefix: string;
  errors: string[];
}

export class PathValidatorError extends Error {
  constructor(
    message: string,
    public readonly code: string,
    public readonly path?: string,
  ) {
    super(message);
    this.name = 'PathValidatorError';
  }
}

/**
 * Dangerous path patterns that indicate traversal attempts.
 */
const TRAVERSAL_PATTERNS = [
  /\.\.\//,              // ../
  /\.\.\\/,              // ..\
  /\.\./,                // .. anywhere
  /%2e%2e/i,             // URL-encoded ..
  /%252e%252e/i,         // Double URL-encoded ..
  /\.%2e/i,              // Mixed encoding
  /%2e\./i,              // Mixed encoding
  /\0/,                  // Null byte
  /%00/,                 // URL-encoded null
];

/**
 * Default blocked file extensions (sensitive files).
 */
const DEFAULT_BLOCKED_EXTENSIONS = [
  '.env',
  '.pem',
  '.key',
  '.crt',
  '.pfx',
  '.p12',
  '.jks',
  '.keystore',
  '.secret',
  '.credentials',
];

/**
 * Default blocked file names (sensitive files).
 */
const DEFAULT_BLOCKED_NAMES = [
  'id_rsa',
  'id_dsa',
  'id_ecdsa',
  'id_ed25519',
  '.htpasswd',
  '.htaccess',
  'shadow',
  'passwd',
  'authorized_keys',
  'known_hosts',
  '.git',
  '.gitconfig',
  '.npmrc',
  '.docker',
];

/**
 * Canonicalizes a path that may not exist yet, by resolving the longest
 * ancestor that DOES exist and re-attaching the remaining segments.
 *
 * Plain `realpath` throws ENOENT for a path whose leaf is missing, which
 * would leave the caller comparing a canonical prefix against a merely
 * lexical candidate — the asymmetry this whole helper exists to avoid.
 * Walking up also means a symlinked PARENT is still resolved, so a
 * not-yet-created file under a symlinked directory canonicalizes to its
 * real location instead of its lexical one.
 *
 * Falls back to the lexical path if the ancestor walk itself fails (EACCES,
 * ELOOP, …), preserving the previous behaviour rather than throwing out of
 * a validation call.
 */
async function canonicalize(resolvedPath: string): Promise<string> {
  try {
    return await fs.realpath(resolvedPath);
  } catch (error: any) {
    if (error?.code !== 'ENOENT') {
      return resolvedPath;
    }
  }

  const parent = path.dirname(resolvedPath);
  // dirname() of a root ('/' or 'C:\\') is itself — stop instead of recursing.
  if (parent === resolvedPath) {
    return resolvedPath;
  }

  return path.join(await canonicalize(parent), path.basename(resolvedPath));
}

/**
 * Synchronous twin of {@link canonicalize}, for the constructor and
 * {@link PathValidator.addPrefix} which cannot await.
 */
function canonicalizeSync(resolvedPath: string): string {
  try {
    return realpathSync(resolvedPath);
  } catch (error: any) {
    if (error?.code !== 'ENOENT') {
      return resolvedPath;
    }
  }

  const parent = path.dirname(resolvedPath);
  if (parent === resolvedPath) {
    return resolvedPath;
  }

  return path.join(canonicalizeSync(parent), path.basename(resolvedPath));
}

/**
 * True if `resolvedPath` is the prefix itself or sits underneath it.
 *
 * The separator has to be appended to anchor the match at a path boundary, so
 * `/srv/app-secrets` does not count as inside `/srv/app` — but a root prefix
 * (`/`, `C:\`, a UNC share root) already ends in one, and appending a second
 * looked for `//`, which rejected every descendant of a root prefix.
 */
function isWithinPrefix(resolvedPath: string, prefix: string): boolean {
  if (resolvedPath === prefix) {
    return true;
  }
  const boundary = prefix.endsWith(path.sep) ? prefix : prefix + path.sep;
  return resolvedPath.startsWith(boundary);
}

/**
 * Path validator that prevents traversal attacks.
 *
 * This class validates file paths to ensure they stay within
 * allowed directories and don't access sensitive files.
 *
 * @example
 * ```typescript
 * const validator = new PathValidator({
 *   allowedPrefixes: ['/workspaces/project']
 * });
 *
 * const result = await validator.validate('/workspaces/project/src/file.ts');
 * if (result.isValid) {
 *   // Safe to use result.resolvedPath
 * }
 * ```
 */
export class PathValidator {
  private readonly config: Required<PathValidatorConfig>;
  /** Lexically resolved prefixes — compared against lexically resolved candidates. */
  private readonly resolvedPrefixes: string[];
  /**
   * Symlink-resolved prefixes — compared against symlink-resolved candidates.
   *
   * Kept as a SECOND list rather than replacing `resolvedPrefixes`, because
   * the two comparison sites derive their candidate differently: `validate()`
   * canonicalizes through the filesystem, `validateSync()`/`isWithinAllowed()`
   * are documented as lexical-only. Canonicalizing one side without the other
   * is exactly the bug this fixes, in whichever direction it is done.
   *
   * Resolved once, at construction — so an allowed prefix denotes the
   * directory it named when the validator was configured, and retargeting a
   * symlink afterwards cannot silently redirect the allowlist. Re-resolving on
   * every call would hand that control to whoever can write the link, and cost
   * a syscall per validation. Callers needing to follow a moved target should
   * construct a new validator.
   */
  private readonly canonicalPrefixes: string[];

  constructor(config: PathValidatorConfig) {
    this.config = {
      allowedPrefixes: config.allowedPrefixes,
      blockedExtensions: config.blockedExtensions ?? DEFAULT_BLOCKED_EXTENSIONS,
      blockedNames: config.blockedNames ?? DEFAULT_BLOCKED_NAMES,
      maxPathLength: config.maxPathLength ?? 4096,
      resolveSymlinks: config.resolveSymlinks ?? true,
      allowNonExistent: config.allowNonExistent ?? true,
      allowHidden: config.allowHidden ?? false,
    };

    if (this.config.allowedPrefixes.length === 0) {
      throw new PathValidatorError(
        'At least one allowed prefix must be specified',
        'EMPTY_PREFIXES'
      );
    }

    // Pre-resolve all prefixes, lexically and canonically. #3010 — validate()
    // canonicalizes the *candidate* through fs.realpath (when resolveSymlinks
    // is on, the default) but prefixes were only ever path.resolve()d, never
    // realpath'd. On any platform where the prefix itself is reached through a
    // symlink (e.g. macOS os.tmpdir() -> /var/folders/... while /var is itself
    // a symlink to /private/var), the realpath'd candidate can never match the
    // non-realpath'd prefix, and every path under that prefix is rejected as
    // "outside allowed directories" — including the prefix's own contents.
    this.resolvedPrefixes = this.config.allowedPrefixes.map(p =>
      path.resolve(p)
    );
    // Always a distinct array — `addPrefix` appends to both, so aliasing the
    // lexical list would push twice. With resolveSymlinks off no candidate is
    // ever canonicalized and nothing reads this list, so skip the syscall.
    this.canonicalPrefixes = this.resolvedPrefixes.map(p =>
      this.config.resolveSymlinks ? canonicalizeSync(p) : p
    );
  }

  /**
   * Validates a path against security rules.
   *
   * @param inputPath - The path to validate
   * @returns Validation result with resolved path
   */
  async validate(inputPath: string): Promise<PathValidationResult> {
    const errors: string[] = [];

    // Check for empty path
    if (!inputPath || inputPath.trim() === '') {
      return {
        isValid: false,
        resolvedPath: '',
        relativePath: '',
        matchedPrefix: '',
        errors: ['Path is empty'],
      };
    }

    // Check path length
    if (inputPath.length > this.config.maxPathLength) {
      return {
        isValid: false,
        resolvedPath: '',
        relativePath: '',
        matchedPrefix: '',
        errors: [`Path exceeds maximum length of ${this.config.maxPathLength}`],
      };
    }

    // Check for traversal patterns
    for (const pattern of TRAVERSAL_PATTERNS) {
      if (pattern.test(inputPath)) {
        return {
          isValid: false,
          resolvedPath: '',
          relativePath: '',
          matchedPrefix: '',
          errors: ['Path traversal pattern detected'],
        };
      }
    }

    // Resolve the path
    let resolvedPath: string;
    // Which prefix list this candidate may legitimately be compared against:
    // only a symlink-resolved candidate may be matched against symlink-resolved
    // prefixes. See `canonicalPrefixes`.
    let symlinksResolved = false;
    try {
      resolvedPath = path.resolve(inputPath);

      // Optionally resolve symlinks
      if (this.config.resolveSymlinks) {
        try {
          resolvedPath = await fs.realpath(resolvedPath);
          symlinksResolved = true;
        } catch (error: any) {
          // Path doesn't exist yet - use resolved path
          if (error.code !== 'ENOENT' || !this.config.allowNonExistent) {
            if (error.code === 'ENOENT') {
              errors.push('Path does not exist');
            } else {
              errors.push(`Failed to resolve path: ${error.message}`);
            }
          }
          if (error.code === 'ENOENT' && this.config.allowNonExistent) {
            // The leaf does not exist, but its ancestors may still be
            // symlinks. Canonicalize what exists so the candidate is in the
            // same form as `canonicalPrefixes` — otherwise every not-yet-
            // created path under a symlinked prefix (macOS `/var` ->
            // `/private/var`, `/tmp` -> `/private/tmp`) fails to match.
            //
            // Only when non-existent paths are actually allowed: with
            // `allowNonExistent: false` this call is already a failure, and
            // canonicalizing anyway would change the `resolvedPath` and
            // `matchedPrefix` reported to callers for no benefit.
            resolvedPath = await canonicalize(resolvedPath);
            symlinksResolved = true;
          }
        }
      }
    } catch (error: any) {
      return {
        isValid: false,
        resolvedPath: '',
        relativePath: '',
        matchedPrefix: '',
        errors: [`Invalid path: ${error.message}`],
      };
    }

    // Check against allowed prefixes
    let matchedPrefix = '';
    let relativePath = '';
    let prefixMatched = false;

    const prefixes = symlinksResolved
      ? this.canonicalPrefixes
      : this.resolvedPrefixes;

    for (const prefix of prefixes) {
      if (isWithinPrefix(resolvedPath, prefix)) {
        prefixMatched = true;
        matchedPrefix = prefix;
        relativePath = resolvedPath.slice(prefix.length);
        if (relativePath.startsWith(path.sep)) {
          relativePath = relativePath.slice(1);
        }
        break;
      }
    }

    if (!prefixMatched) {
      return {
        isValid: false,
        resolvedPath,
        relativePath: '',
        matchedPrefix: '',
        errors: ['Path is outside allowed directories'],
      };
    }

    // Check for hidden files
    const pathParts = resolvedPath.split(path.sep);
    if (!this.config.allowHidden) {
      for (const part of pathParts) {
        if (part.startsWith('.') && part !== '.' && part !== '..') {
          errors.push('Hidden files/directories are not allowed');
          break;
        }
      }
    }

    // Check blocked file names
    const basename = path.basename(resolvedPath);
    if (this.config.blockedNames.includes(basename)) {
      errors.push(`File name "${basename}" is blocked`);
    }

    // Check blocked extensions
    const ext = path.extname(resolvedPath).toLowerCase();
    if (this.config.blockedExtensions.includes(ext)) {
      errors.push(`File extension "${ext}" is blocked`);
    }

    // Also check for double extensions (e.g., .tar.gz, .config.json)
    const fullname = basename.toLowerCase();
    for (const blockedExt of this.config.blockedExtensions) {
      if (fullname.endsWith(blockedExt)) {
        errors.push(`File extension "${blockedExt}" is blocked`);
        break;
      }
    }

    return {
      isValid: errors.length === 0,
      resolvedPath,
      relativePath,
      matchedPrefix,
      errors,
    };
  }

  /**
   * Validates and returns resolved path, throwing on failure.
   *
   * @param inputPath - The path to validate
   * @returns Resolved path if valid
   * @throws PathValidatorError if validation fails
   */
  async validateOrThrow(inputPath: string): Promise<string> {
    const result = await this.validate(inputPath);

    if (!result.isValid) {
      throw new PathValidatorError(
        result.errors.join('; '),
        'VALIDATION_FAILED',
        inputPath
      );
    }

    return result.resolvedPath;
  }

  /**
   * Synchronous validation (without symlink resolution).
   *
   * @param inputPath - The path to validate
   * @returns Validation result
   */
  validateSync(inputPath: string): PathValidationResult {
    const errors: string[] = [];

    if (!inputPath || inputPath.trim() === '') {
      return {
        isValid: false,
        resolvedPath: '',
        relativePath: '',
        matchedPrefix: '',
        errors: ['Path is empty'],
      };
    }

    if (inputPath.length > this.config.maxPathLength) {
      return {
        isValid: false,
        resolvedPath: '',
        relativePath: '',
        matchedPrefix: '',
        errors: [`Path exceeds maximum length of ${this.config.maxPathLength}`],
      };
    }

    for (const pattern of TRAVERSAL_PATTERNS) {
      if (pattern.test(inputPath)) {
        return {
          isValid: false,
          resolvedPath: '',
          relativePath: '',
          matchedPrefix: '',
          errors: ['Path traversal pattern detected'],
        };
      }
    }

    const resolvedPath = path.resolve(inputPath);

    let matchedPrefix = '';
    let relativePath = '';
    let prefixMatched = false;

    for (const prefix of this.resolvedPrefixes) {
      if (isWithinPrefix(resolvedPath, prefix)) {
        prefixMatched = true;
        matchedPrefix = prefix;
        relativePath = resolvedPath.slice(prefix.length);
        if (relativePath.startsWith(path.sep)) {
          relativePath = relativePath.slice(1);
        }
        break;
      }
    }

    if (!prefixMatched) {
      return {
        isValid: false,
        resolvedPath,
        relativePath: '',
        matchedPrefix: '',
        errors: ['Path is outside allowed directories'],
      };
    }

    const pathParts = resolvedPath.split(path.sep);
    if (!this.config.allowHidden) {
      for (const part of pathParts) {
        if (part.startsWith('.') && part !== '.' && part !== '..') {
          errors.push('Hidden files/directories are not allowed');
          break;
        }
      }
    }

    const basename = path.basename(resolvedPath);
    if (this.config.blockedNames.includes(basename)) {
      errors.push(`File name "${basename}" is blocked`);
    }

    const ext = path.extname(resolvedPath).toLowerCase();
    if (this.config.blockedExtensions.includes(ext)) {
      errors.push(`File extension "${ext}" is blocked`);
    }

    return {
      isValid: errors.length === 0,
      resolvedPath,
      relativePath,
      matchedPrefix,
      errors,
    };
  }

  /**
   * Securely joins path segments within allowed directories.
   *
   * @param prefix - Base directory (must be in allowedPrefixes)
   * @param segments - Path segments to join
   * @returns Validated resolved path
   */
  async securePath(prefix: string, ...segments: string[]): Promise<string> {
    // Join the segments
    const joined = path.join(prefix, ...segments);

    // Validate the result
    return this.validateOrThrow(joined);
  }

  /**
   * Adds a prefix to the allowed list at runtime.
   *
   * @param prefix - Prefix to add
   */
  addPrefix(prefix: string): void {
    const resolved = path.resolve(prefix);
    if (!this.resolvedPrefixes.includes(resolved)) {
      this.config.allowedPrefixes.push(prefix);
      this.resolvedPrefixes.push(resolved);
      this.canonicalPrefixes.push(
        this.config.resolveSymlinks ? canonicalizeSync(resolved) : resolved
      );
    }
  }

  /**
   * Returns the current allowed prefixes.
   */
  getAllowedPrefixes(): readonly string[] {
    return [...this.resolvedPrefixes];
  }

  /**
   * Checks if a path is within allowed prefixes (quick check).
   */
  isWithinAllowed(inputPath: string): boolean {
    try {
      const resolved = path.resolve(inputPath);
      return this.resolvedPrefixes.some(
        prefix => isWithinPrefix(resolved, prefix)
      );
    } catch {
      return false;
    }
  }
}

/**
 * Factory function to create a path validator for a project directory.
 *
 * @param projectRoot - Root directory of the project
 * @returns Configured PathValidator
 */
export function createProjectPathValidator(projectRoot: string): PathValidator {
  const srcDir = path.join(projectRoot, 'src');
  const testDir = path.join(projectRoot, 'tests');
  const docsDir = path.join(projectRoot, 'docs');

  return new PathValidator({
    allowedPrefixes: [srcDir, testDir, docsDir],
    allowHidden: false,
  });
}

/**
 * Factory function to create a path validator for the entire project.
 *
 * @param projectRoot - Root directory of the project
 * @returns Configured PathValidator
 */
export function createFullProjectPathValidator(projectRoot: string): PathValidator {
  return new PathValidator({
    allowedPrefixes: [projectRoot],
    allowHidden: true, // Allow .gitignore, etc.
    blockedNames: [
      ...DEFAULT_BLOCKED_NAMES,
      'node_modules', // Block access to node_modules
    ],
  });
}

/**
 * PluginIntegrityVerifier — install-layer security for plugin supply chain.
 *
 * Implements P1 of ADR-145 (ruvnet/ruflo#2254): Stage-1 Ed25519 signature
 * verification at `plugins install`. Stage-2 (semantic-intent scan against
 * SCH attacks) lands in P2; per-namespace write ACLs land in P3-P4.
 *
 * Threat model
 * ------------
 * Ruflo's plugin install path fetches manifests from IPFS via Pinata with
 * NO signature verification and NO intent analysis. Two attacks land today:
 *
 *   - DDIPE (arXiv:2604.03081): malicious logic embedded in plugin docs and
 *     config templates. 11.6-33.5% bypass rate across 4 frameworks/5 models;
 *     2.5% evade both detection and alignment. Stage-1 signing blocks the
 *     static-payload variants.
 *
 *   - SCH (arXiv:2605.14460): malicious intent wrapped as natural-language
 *     "compliance rules" in plugin descriptions. The agent generates the
 *     harmful code at runtime — no static payload exists. 77.67% breach
 *     success, 0.00% scanner detection. Stage-2 (P2) catches this; Stage-1
 *     does not.
 *
 * Scope (P1)
 * ----------
 * - Ed25519 signature verification of a detached signature over the manifest.
 * - Trust-anchor allowlist: the publisher's signing key fingerprint must be
 *   in `trust-anchors.json`, gated on CODEOWNERS review.
 * - Backwards compatible: default mode is warn-only. `CLAUDE_FLOW_STRICT_PLUGINS=true`
 *   makes verification a hard gate.
 *
 * Non-goals (P1)
 * --------------
 * - Semantic intent scan (SCH defence). Lands in P2 with a pattern-rule
 *   fallback for environments without LLM credentials.
 * - Sandboxing the plugin runtime. Orthogonal blast-radius concern.
 *
 * Reference: ADR-145, arXiv:2605.14460 (SCH), arXiv:2604.03081 (DDIPE),
 * arXiv:2604.16548 (Mnemonic Sovereignty survey).
 */

import { createHash } from 'node:crypto';
import * as nodeCrypto from 'node:crypto';

export interface PluginManifest {
  readonly id: string;
  readonly version: string;
  /** Anything else; only `id` + `version` matter for the integrity hash. */
  readonly [extra: string]: unknown;
}

export interface SignedPluginManifest {
  readonly manifest: PluginManifest;
  /** Hex-encoded SHA-256 of the canonical JSON serialisation of manifest. */
  readonly manifestHash: string;
  /** Hex-encoded detached Ed25519 signature over `manifestHash` bytes. */
  readonly signature: string;
  /** Hex-encoded Ed25519 public key of the signer. */
  readonly publicKey: string;
}

export interface TrustAnchor {
  /** Hex-encoded Ed25519 public key the publisher signs with. */
  readonly publicKey: string;
  /** Human-readable owner — for audit, not for trust decisions. */
  readonly owner: string;
  /** Optional ISO 8601 date after which this anchor is no longer trusted. */
  readonly expiresAt?: string;
  /** Optional plugin id glob this anchor is authoritative for (e.g. `@claude-flow/*`). */
  readonly scope?: string;
}

export interface TrustAnchors {
  readonly version: 1;
  readonly anchors: ReadonlyArray<TrustAnchor>;
}

export type VerificationStatus =
  | 'pass'
  | 'signature-missing'
  | 'signature-invalid'
  | 'manifest-hash-mismatch'
  | 'unknown-signer'
  | 'signer-expired'
  | 'signer-out-of-scope';

export interface VerificationResult {
  readonly status: VerificationStatus;
  readonly pluginId: string;
  readonly signerFingerprint?: string;
  /** Verification timestamp — useful for telemetry correlation. */
  readonly ts: number;
  /** Operator-facing detail; do not parse — log only. */
  readonly detail?: string;
}

export interface VerifierConfig {
  readonly trustAnchors: TrustAnchors;
  /**
   * When true, `verify` returns the actual failure status. When false (legacy
   * mode), `verify` returns the failure status BUT callers may choose to
   * proceed with a warning — the strictness gate lives at the caller, not
   * here, so the verifier itself is always pure.
   */
  readonly strict?: boolean;
  /** Optional now-provider for tests. */
  readonly now?: () => number;
}

/**
 * Canonical JSON serialisation for hashing. Deterministic key ordering at
 * every nesting level. Pure; identical input → identical output bytes.
 */
export function canonicalize(value: unknown): string {
  if (value === null || typeof value !== 'object') return JSON.stringify(value);
  if (Array.isArray(value)) return '[' + value.map(canonicalize).join(',') + ']';
  const obj = value as Record<string, unknown>;
  const keys = Object.keys(obj).sort();
  return '{' + keys.map(k => JSON.stringify(k) + ':' + canonicalize(obj[k])).join(',') + '}';
}

/** Hex-encoded SHA-256 of the canonical-JSON manifest. */
export function hashManifest(manifest: PluginManifest): string {
  return createHash('sha256').update(canonicalize(manifest)).digest('hex');
}

/** Short fingerprint for telemetry — first 16 hex chars of the key. */
export function fingerprint(publicKey: string): string {
  return publicKey.slice(0, 16);
}

/**
 * Find the trust anchor that vouches for a manifest. Returns the matched
 * anchor (with anchor.publicKey === signer.publicKey) or null.
 *
 * Scope-matching uses a minimal glob: `*` at the end of the scope string
 * matches any suffix. Empty/missing scope matches every plugin id.
 */
export function findAnchor(
  anchors: ReadonlyArray<TrustAnchor>,
  pluginId: string,
  signerPublicKey: string,
  now: number,
): TrustAnchor | null {
  for (const a of anchors) {
    if (a.publicKey !== signerPublicKey) continue;
    if (a.expiresAt && new Date(a.expiresAt).getTime() <= now) continue;
    if (!a.scope || a.scope === '*' || a.scope === pluginId) return a;
    if (a.scope.endsWith('*') && pluginId.startsWith(a.scope.slice(0, -1))) return a;
  }
  return null;
}

/**
 * `PluginIntegrityVerifier` — Stage-1 verifier (signature + trust anchor).
 *
 * Pure-ish: holds the trust-anchor list and clock, no other state. Safe to
 * construct per-invocation or share.
 */
export class PluginIntegrityVerifier {
  constructor(private readonly config: VerifierConfig) {}

  /**
   * Verify a signed manifest. Returns the verification status; the caller
   * decides what to do with `signature-missing` / `manifest-hash-mismatch`
   * etc. based on its strict-mode policy.
   */
  async verify(signed: SignedPluginManifest): Promise<VerificationResult> {
    const now = (this.config.now ?? Date.now)();
    const pluginId = signed.manifest?.id ?? '<unknown>';

    if (!signed.signature || !signed.publicKey) {
      return { status: 'signature-missing', pluginId, ts: now };
    }

    // Re-hash the manifest and compare to the signed hash.
    const recomputed = hashManifest(signed.manifest);
    if (recomputed !== signed.manifestHash) {
      return {
        status: 'manifest-hash-mismatch',
        pluginId,
        signerFingerprint: fingerprint(signed.publicKey),
        ts: now,
        detail: `expected ${signed.manifestHash}, got ${recomputed}`,
      };
    }

    // Find a trust anchor that vouches for this signer + plugin.
    const anchor = findAnchor(this.config.trustAnchors.anchors, pluginId, signed.publicKey, now);
    if (!anchor) {
      return {
        status: 'unknown-signer',
        pluginId,
        signerFingerprint: fingerprint(signed.publicKey),
        ts: now,
      };
    }

    // Ed25519 verify. Probe @noble/ed25519 (already a workspace dep); fall
    // back to the failure status if it isn't resolvable in this environment
    // (mirrors verify.mjs's #1880 precondition pattern).
    const ed = await loadEd25519();
    if (!ed) {
      return {
        status: 'signature-invalid',
        pluginId,
        signerFingerprint: fingerprint(signed.publicKey),
        ts: now,
        detail: '@noble/ed25519 not available — cannot verify',
      };
    }

    // Required by @noble/ed25519 v2 for sync sha512.
    if (!ed.etc.sha512Sync) {
      ed.etc.sha512Sync = (...m: Uint8Array[]): Uint8Array => {
        const h = nodeCrypto.createHash('sha512');
        for (const x of m) h.update(x);
        return h.digest();
      };
    }

    let ok = false;
    try {
      const sigBytes = hexToBytes(signed.signature);
      const msgBytes = hexToBytes(signed.manifestHash);
      const pubBytes = hexToBytes(signed.publicKey);
      ok = await ed.verify(sigBytes, msgBytes, pubBytes);
    } catch {
      ok = false;
    }

    if (!ok) {
      return {
        status: 'signature-invalid',
        pluginId,
        signerFingerprint: fingerprint(signed.publicKey),
        ts: now,
      };
    }

    return { status: 'pass', pluginId, signerFingerprint: fingerprint(signed.publicKey), ts: now };
  }
}

// ─── helpers ────────────────────────────────────────────────────────────

function hexToBytes(hex: string): Uint8Array {
  const out = new Uint8Array(hex.length >>> 1);
  for (let i = 0; i < out.length; i++) out[i] = parseInt(hex.substr(i * 2, 2), 16);
  return out;
}

interface NobleEd25519 {
  verify(sig: Uint8Array, msg: Uint8Array, pub: Uint8Array): Promise<boolean>;
  etc: { sha512Sync?: (...m: Uint8Array[]) => Uint8Array };
}

async function loadEd25519(): Promise<NobleEd25519 | null> {
  try {
    const mod = await import('@noble/ed25519');
    return mod as unknown as NobleEd25519;
  } catch {
    return null;
  }
}

import { createHash, createHmac, timingSafeEqual } from 'node:crypto';

function normalize(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(normalize);
  if (value && typeof value === 'object') {
    return Object.fromEntries(
      Object.entries(value as Record<string, unknown>)
        .filter(([, item]) => item !== undefined)
        .sort(([a], [b]) => a.localeCompare(b))
        .map(([key, item]) => [key, normalize(item)]),
    );
  }
  if (typeof value === 'number' && !Number.isFinite(value)) {
    throw new TypeError('Policy canonicalization rejects non-finite numbers');
  }
  return value;
}

export function canonicalizePolicy(value: unknown): string {
  return JSON.stringify(normalize(value));
}

export function policyHash(value: unknown): string {
  return `sha256:${createHash('sha256').update(canonicalizePolicy(value)).digest('hex')}`;
}

export function signPolicyHash(hash: string, key: string | Buffer): string {
  return createHmac('sha256', key).update(hash).digest('base64url');
}

export function verifyPolicySignature(hash: string, signature: string, key: string | Buffer): boolean {
  const expected = Buffer.from(signPolicyHash(hash, key));
  const actual = Buffer.from(signature);
  return expected.length === actual.length && timingSafeEqual(expected, actual);
}

import { policyHash, signPolicyHash, verifyPolicySignature } from './canonical.js';
import { evaluatePolicy } from './evaluator.js';
import type {
  BudgetLimit,
  BudgetUsage,
  PolicyApproval,
  PolicyDecision,
  PolicyEvidence,
  PolicyEngineOptions,
  PolicyReceipt,
  PolicyRequest,
  PolicyRule,
  PolicyState,
} from './types.js';
import { POLICY_STATE_VERSION } from './types.js';

function wildcard(pattern: string | undefined, value: string | undefined): boolean {
  if (!pattern) return true;
  if (!value) return false;
  return pattern === '*' || pattern === value || (pattern.endsWith('*') && value.startsWith(pattern.slice(0, -1)));
}

export class AgenticPolicyEngine {
  private readonly now: () => number;
  private readonly signingKey?: string | Buffer;
  private readonly keyId?: string;
  private readonly evidenceVerifier?: (evidence: PolicyEvidence, request: PolicyRequest) => boolean;
  private readonly approvalIssuerVerifier?: (issuer: string) => boolean;
  private state: PolicyState;

  constructor(options: PolicyEngineOptions = {}) {
    this.now = options.now ?? Date.now;
    this.signingKey = options.signingKey;
    this.keyId = options.keyId;
    this.evidenceVerifier = options.evidenceVerifier;
    this.approvalIssuerVerifier = options.approvalIssuerVerifier;
    this.state = {
      version: POLICY_STATE_VERSION,
      mode: options.mode ?? 'legacy',
      rules: [...(options.rules ?? [])],
      budgets: [...(options.budgets ?? [])],
      usage: [...(options.usage ?? [])],
      approvals: [...(options.approvals ?? [])],
      receipts: [...(options.receipts ?? [])],
    };
  }

  static fromState(state: PolicyState, options: Omit<PolicyEngineOptions, 'mode' | 'rules' | 'budgets' | 'usage' | 'approvals' | 'receipts'> = {}): AgenticPolicyEngine {
    const engine = new AgenticPolicyEngine({
      ...options,
      mode: state.mode,
      rules: state.rules,
      budgets: state.budgets,
      usage: state.usage,
      approvals: state.approvals,
      receipts: state.receipts,
    });
    engine.state.migratedAt = state.migratedAt;
    engine.state.migratedFrom = state.migratedFrom;
    engine.state.configuredMode = state.configuredMode;
    return engine;
  }

  exportState(): PolicyState {
    return structuredClone(this.state);
  }

  setMode(mode: PolicyState['mode']): void {
    this.state.mode = mode;
  }

  setConfiguredMode(mode: PolicyState['mode']): void {
    this.state.configuredMode = mode;
    const rank = { legacy: 0, observe: 1, enforce: 2 } as const;
    if (rank[mode] > rank[this.state.mode]) this.state.mode = mode;
  }

  upsertRule(rule: PolicyRule): void {
    if (!rule.id || !rule.actions.length) throw new Error('invalid-policy-rule');
    for (const value of [
      rule.constraints?.maxCostUsd,
      rule.constraints?.maxTokens,
      rule.constraints?.maxConcurrency,
    ]) {
      if (value !== undefined && (!Number.isFinite(value) || value < 0)) {
        throw new Error('invalid-policy-rule-limit');
      }
    }
    const index = this.state.rules.findIndex((item) => item.id === rule.id);
    if (index >= 0) this.state.rules[index] = structuredClone(rule);
    else this.state.rules.push(structuredClone(rule));
  }

  setBudget(limit: BudgetLimit): void {
    if (limit.periodMs <= 0) throw new Error('invalid-budget-period');
    if (!Number.isFinite(limit.periodMs)
      || [limit.maxCostUsd, limit.maxTokens].some((value) => (
        value !== undefined && (!Number.isFinite(value) || value < 0)
      ))) throw new Error('invalid-budget-limit');
    const index = this.state.budgets.findIndex((item) => item.id === limit.id);
    if (index >= 0) this.state.budgets[index] = structuredClone(limit);
    else this.state.budgets.push(structuredClone(limit));
  }

  issueApproval(approval: Omit<PolicyApproval, 'uses' | 'issuedAt'> & { uses?: number; issuedAt?: number }): PolicyApproval {
    if (approval.issuedBy === approval.principal) throw new Error('self-approval-forbidden');
    if (this.approvalIssuerVerifier?.(approval.issuedBy) !== true) {
      throw new Error('untrusted-approval-issuer');
    }
    const issuedAt = approval.issuedAt ?? this.now();
    const record: PolicyApproval = { ...approval, issuedAt, uses: approval.uses ?? 0 };
    if (this.state.approvals.some((item) => item.id === record.id)) throw new Error('duplicate-approval-id');
    if (!record.id
      || record.expiresAt <= issuedAt
      || !Number.isInteger(record.maxUses)
      || record.maxUses <= 0
      || !Number.isInteger(record.uses)
      || record.uses < 0
      || record.uses > record.maxUses) throw new Error('invalid-approval');
    this.state.approvals.push(record);
    return structuredClone(record);
  }

  revokeApproval(id: string): boolean {
    const approval = this.state.approvals.find((item) => item.id === id);
    if (!approval || approval.revokedAt) return false;
    approval.revokedAt = this.now();
    return true;
  }

  evaluate(request: PolicyRequest): PolicyDecision {
    const normalized: PolicyRequest = {
      ...request,
      requestId: request.requestId ?? crypto.randomUUID(),
      // Caller time is evidence only; expiry, budgets, and receipts always use
      // the authority's clock.
      context: { ...request.context, now: this.now() },
    };
    this.validateRequest(normalized);
    const verifiedEvidenceIds = (normalized.context?.evidence ?? [])
      .filter((evidence) => evidence.id && this.evidenceVerifier?.(evidence, normalized) === true)
      .map((evidence) => evidence.id!);
    let decision = evaluatePolicy(normalized, this.state.rules, this.state.mode, verifiedEvidenceIds);
    decision = this.applyBudget(normalized, decision);
    decision = this.applyApproval(normalized, decision);
    const receipt = this.appendReceipt(normalized, decision);
    this.consumeBudget(normalized, decision);
    return { ...decision, receiptId: receipt.payload.receiptId };
  }

  verifyLedger(): { valid: boolean; length: number; error?: string } {
    let previous: string | null = null;
    for (let i = 0; i < this.state.receipts.length; i++) {
      const receipt = this.state.receipts[i]!;
      if (receipt.payload.sequence !== i || receipt.payload.previousReceiptHash !== previous) {
        return { valid: false, length: i, error: 'receipt-chain-mismatch' };
      }
      const hash = policyHash(receipt.payload);
      const { receiptId, ...unsignedIdPayload } = receipt.payload;
      if (hash !== receipt.hash || receiptId !== policyHash(unsignedIdPayload)) {
        return { valid: false, length: i, error: 'receipt-hash-mismatch' };
      }
      if (this.signingKey && !receipt.signature) {
        return { valid: false, length: i, error: 'receipt-signature-missing' };
      }
      if (receipt.signature && !this.signingKey) {
        return { valid: false, length: i, error: 'receipt-signing-key-required' };
      }
      if (receipt.signature && this.signingKey && !verifyPolicySignature(hash, receipt.signature, this.signingKey)) {
        return { valid: false, length: i, error: 'receipt-signature-invalid' };
      }
      previous = receipt.hash;
    }
    return { valid: true, length: this.state.receipts.length };
  }

  private applyBudget(request: PolicyRequest, decision: Omit<PolicyDecision, 'receiptId'>): Omit<PolicyDecision, 'receiptId'> {
    if (decision.outcome === 'denied') return decision;
    const now = request.context?.now ?? this.now();
    for (const limit of this.state.budgets) {
      if (!wildcard(limit.principal, request.identity.id)
        || !wildcard(limit.action, request.action.type)
        || !wildcard(limit.resource, request.action.resource)) continue;
      let usage = this.state.usage.find((item) => item.limitId === limit.id);
      if (!usage || now - usage.windowStartedAt >= limit.periodMs) {
        usage = { limitId: limit.id, windowStartedAt: now, costUsd: 0, tokens: 0 };
      }
      if (limit.maxCostUsd !== undefined && usage.costUsd + (request.action.costUsd ?? 0) > limit.maxCostUsd) {
        return { ...decision, outcome: 'denied', enforcedOutcome: this.state.mode === 'enforce' ? 'denied' : 'allowed', reason: `budget-exceeded:${limit.id}` };
      }
      if (limit.maxCostUsd !== undefined && request.action.costUsd === undefined) {
        return { ...decision, outcome: 'denied', enforcedOutcome: this.state.mode === 'enforce' ? 'denied' : 'allowed', reason: `budget-metering-required:${limit.id}:costUsd` };
      }
      if (limit.maxTokens !== undefined && request.action.tokens === undefined) {
        return { ...decision, outcome: 'denied', enforcedOutcome: this.state.mode === 'enforce' ? 'denied' : 'allowed', reason: `budget-metering-required:${limit.id}:tokens` };
      }
      if (limit.maxTokens !== undefined && usage.tokens + (request.action.tokens ?? 0) > limit.maxTokens) {
        return { ...decision, outcome: 'denied', enforcedOutcome: this.state.mode === 'enforce' ? 'denied' : 'allowed', reason: `budget-exceeded:${limit.id}` };
      }
    }
    return decision;
  }

  private applyApproval(request: PolicyRequest, decision: Omit<PolicyDecision, 'receiptId'>): Omit<PolicyDecision, 'receiptId'> {
    if (decision.outcome !== 'approval_required') return decision;
    const now = request.context?.now ?? this.now();
    const ids = new Set(request.context?.approvalIds ?? []);
    const approval = this.state.approvals.find((item) => (
      ids.has(item.id)
      && !item.revokedAt
      && item.expiresAt > now
      && item.uses < item.maxUses
      && wildcard(item.principal, request.identity.id)
      && item.actions.some((action) => wildcard(action, request.action.type))
      && (!item.resources?.length || item.resources.some((resource) => wildcard(resource, request.action.resource)))
    ));
    if (!approval) return decision;
    approval.uses += 1;
    return {
      ...decision,
      outcome: 'allowed',
      enforcedOutcome: 'allowed',
      reason: `approved-by:${approval.id}`,
      approvalId: approval.id,
      obligations: [],
    };
  }

  private consumeBudget(request: PolicyRequest, decision: Omit<PolicyDecision, 'receiptId'>): void {
    if (decision.enforcedOutcome !== 'allowed') return;
    const now = request.context?.now ?? this.now();
    for (const limit of this.state.budgets) {
      if (!wildcard(limit.principal, request.identity.id)
        || !wildcard(limit.action, request.action.type)
        || !wildcard(limit.resource, request.action.resource)) continue;
      let usage = this.state.usage.find((item) => item.limitId === limit.id);
      if (!usage || now - usage.windowStartedAt >= limit.periodMs) {
        usage = { limitId: limit.id, windowStartedAt: now, costUsd: 0, tokens: 0 };
        this.state.usage = this.state.usage.filter((item) => item.limitId !== limit.id);
        this.state.usage.push(usage);
      }
      usage.costUsd += request.action.costUsd ?? 0;
      usage.tokens += request.action.tokens ?? 0;
    }
  }

  private appendReceipt(request: PolicyRequest, decision: Omit<PolicyDecision, 'receiptId'>): PolicyReceipt {
    const previous = this.state.receipts.at(-1)?.hash ?? null;
    const sequence = this.state.receipts.length;
    const payloadWithoutId = {
      previousReceiptHash: previous,
      sequence,
      issuedAt: request.context?.now ?? this.now(),
      request,
      decision,
      policyHash: policyHash({ mode: this.state.mode, rules: this.state.rules, budgets: this.state.budgets }),
    };
    const receiptId = policyHash(payloadWithoutId);
    const payload = { receiptId, ...payloadWithoutId };
    const hash = policyHash(payload);
    const receipt: PolicyReceipt = {
      payload,
      hash,
      signature: this.signingKey ? signPolicyHash(hash, this.signingKey) : undefined,
      keyId: this.signingKey ? (this.keyId ?? 'local') : undefined,
    };
    this.state.receipts.push(receipt);
    return receipt;
  }

  private validateRequest(request: PolicyRequest): void {
    if (!request.identity?.id || !request.identity.type || !request.action?.type) {
      throw new Error('invalid-policy-request');
    }
    for (const [name, value] of [
      ['costUsd', request.action.costUsd],
      ['tokens', request.action.tokens],
      ['concurrency', request.action.concurrency],
    ] as const) {
      if (value !== undefined && (!Number.isFinite(value) || value < 0)) {
        throw new Error(`invalid-policy-action-${name}`);
      }
    }
  }
}

export function createLegacyCompatibleState(source = 'pre-ADR-324'): PolicyState {
  return {
    version: POLICY_STATE_VERSION,
    mode: 'legacy',
    migratedFrom: source,
    migratedAt: Date.now(),
    rules: [],
    budgets: [],
    usage: [],
    approvals: [],
    receipts: [],
  };
}

import type { CapabilityEnvelope, PolicyAction } from './types.js';

export interface EnvelopeCheck {
  allowed: boolean;
  reason?: string;
}

function matches(patterns: readonly string[] | undefined, value: string | undefined): boolean {
  if (!patterns?.length) return true;
  if (!value) return false;
  return patterns.some((pattern) => (
    pattern === '*'
    || pattern === value
    || (pattern.endsWith('*') && value.startsWith(pattern.slice(0, -1)))
  ));
}

function subset(child: readonly string[] | undefined, parent: readonly string[] | undefined): boolean {
  if (!parent?.length) return true;
  if (!child?.length) return false;
  return child.every((value) => matches(parent, value));
}

export function checkCapabilityEnvelope(
  action: PolicyAction,
  envelope: CapabilityEnvelope | undefined,
  now = Date.now(),
): EnvelopeCheck {
  if (!envelope) return { allowed: true };
  if (envelope.expiresAt !== undefined && envelope.expiresAt <= now) {
    return { allowed: false, reason: 'capability-envelope-expired' };
  }
  const checks: Array<[boolean, string]> = [
    [matches(envelope.actions, action.type), 'action-outside-envelope'],
    [matches(envelope.resources, action.resource), 'resource-outside-envelope'],
    [matches(envelope.tools, action.tool), 'tool-outside-envelope'],
    [matches(envelope.servers, action.server), 'server-outside-envelope'],
    [matches(envelope.environments, action.environment), 'environment-outside-envelope'],
  ];
  if (action.namespace) {
    const namespaces = action.type.includes('read')
      ? envelope.readNamespaces
      : envelope.writeNamespaces;
    checks.push([matches(namespaces, action.namespace), 'namespace-outside-envelope']);
  }
  if (action.costUsd !== undefined && envelope.maxCostUsd !== undefined) {
    checks.push([action.costUsd <= envelope.maxCostUsd, 'cost-outside-envelope']);
  }
  if (action.tokens !== undefined && envelope.maxTokens !== undefined) {
    checks.push([action.tokens <= envelope.maxTokens, 'tokens-outside-envelope']);
  }
  if (action.concurrency !== undefined && envelope.maxConcurrency !== undefined) {
    checks.push([action.concurrency <= envelope.maxConcurrency, 'concurrency-outside-envelope']);
  }
  if (action.network === true) checks.push([envelope.network === true, 'network-outside-envelope']);
  if (action.destructive === true) checks.push([envelope.destructive === true, 'destructive-outside-envelope']);
  const failed = checks.find(([allowed]) => !allowed);
  return failed ? { allowed: false, reason: failed[1] } : { allowed: true };
}

export function isEnvelopeReduction(parent: CapabilityEnvelope, child: CapabilityEnvelope): boolean {
  const listChecks = [
    subset(child.actions, parent.actions),
    subset(child.resources, parent.resources),
    subset(child.tools, parent.tools),
    subset(child.servers, parent.servers),
    subset(child.readNamespaces, parent.readNamespaces),
    subset(child.writeNamespaces, parent.writeNamespaces),
    subset(child.environments, parent.environments),
  ];
  const numericChecks: Array<[number | undefined, number | undefined]> = [
    [child.maxCostUsd, parent.maxCostUsd],
    [child.maxTokens, parent.maxTokens],
    [child.maxConcurrency, parent.maxConcurrency],
    [child.delegationDepth, parent.delegationDepth],
    [child.expiresAt, parent.expiresAt],
  ];
  return listChecks.every(Boolean)
    && numericChecks.every(([next, current]) => (
      current === undefined
        ? true
        : next !== undefined && next <= current
    ))
    && !(child.network === true && parent.network !== true)
    && !(child.destructive === true && parent.destructive !== true);
}

export function delegateEnvelope(
  parent: CapabilityEnvelope,
  child: CapabilityEnvelope,
): CapabilityEnvelope {
  if ((parent.delegationDepth ?? 0) <= 0) {
    throw new Error('delegation-depth-exhausted');
  }
  const reduced = {
    ...parent,
    ...child,
    delegationDepth: Math.min(
      child.delegationDepth ?? Number.MAX_SAFE_INTEGER,
      (parent.delegationDepth ?? 0) - 1,
    ),
    expiresAt: Math.min(
      child.expiresAt ?? Number.MAX_SAFE_INTEGER,
      parent.expiresAt ?? Number.MAX_SAFE_INTEGER,
    ),
  };
  if (!isEnvelopeReduction(parent, reduced)) throw new Error('capability-envelope-cannot-grow');
  return reduced;
}

import { checkCapabilityEnvelope } from './envelope.js';
import type {
  PolicyConstraints,
  PolicyDecision,
  PolicyMode,
  PolicyRequest,
  PolicyRule,
} from './types.js';

function matches(patterns: readonly string[] | undefined, value: string | undefined): boolean {
  if (!patterns?.length) return true;
  if (!value) return false;
  return patterns.some((pattern) => (
    pattern === '*'
    || pattern === value
    || (pattern.endsWith('*') && value.startsWith(pattern.slice(0, -1)))
  ));
}

function constraintsPass(request: PolicyRequest, constraints: PolicyConstraints | undefined): boolean {
  if (!constraints) return true;
  const { action } = request;
  const evidence = request.context?.evidence ?? [];
  const verifiedIds = new Set(
    request.context?.metadata?.verifiedEvidenceIds instanceof Array
      ? request.context.metadata.verifiedEvidenceIds
      : [],
  );
  const verifiedEvidence = evidence.filter((item) => item.id && verifiedIds.has(item.id));
  if (constraints.maxCostUsd !== undefined
    && (action.costUsd === undefined || action.costUsd > constraints.maxCostUsd)) return false;
  if (constraints.maxTokens !== undefined
    && (action.tokens === undefined || action.tokens > constraints.maxTokens)) return false;
  if (constraints.maxConcurrency !== undefined
    && (action.concurrency === undefined || action.concurrency > constraints.maxConcurrency)) return false;
  if (constraints.network === false && action.network === true) return false;
  if (constraints.destructive === false && action.destructive === true) return false;
  if (constraints.allowedNamespaces?.length && !matches(constraints.allowedNamespaces, action.namespace)) return false;
  // Signature verification is performed by the engine's trusted verifier.
  // A caller-authored `signed: true` flag is deliberately ignored.
  if (constraints.requireSignedEvidence && verifiedEvidence.length === 0) return false;
  if (constraints.requiredProvenance?.length) {
    const relevant = constraints.requireSignedEvidence ? verifiedEvidence : evidence;
    const available = new Set(relevant.map((item) => item.provenance));
    if (!constraints.requiredProvenance.every((type) => available.has(type))) return false;
  }
  return true;
}

export function ruleMatches(rule: PolicyRule, request: PolicyRequest): boolean {
  if (rule.enabled === false) return false;
  const { identity, action } = request;
  return matches(rule.actions, action.type)
    && matches(rule.resources, action.resource)
    && matches(rule.principals, identity.id)
    && (!rule.identityTypes?.length || rule.identityTypes.includes(identity.type))
    && (!rule.roles?.length || rule.roles.some((role) => identity.roles?.includes(role)))
    && matches(rule.environments, action.environment)
    && constraintsPass(request, rule.constraints);
}

export function evaluatePolicy(
  request: PolicyRequest,
  rules: readonly PolicyRule[],
  mode: PolicyMode,
  verifiedEvidenceIds: readonly string[] = [],
): Omit<PolicyDecision, 'receiptId'> {
  const requestId = request.requestId ?? crypto.randomUUID();
  const envelope = checkCapabilityEnvelope(
    request.action,
    request.context?.envelope,
    request.context?.now,
  );
  if (!envelope.allowed) {
    return {
      requestId,
      outcome: 'denied',
      // A capability envelope is delegated authority, not an observation-mode
      // rule. Crossing it is always blocked, including legacy installations.
      enforcedOutcome: 'denied',
      mode,
      reason: envelope.reason ?? 'capability-envelope-denied',
      matchedRules: [],
      obligations: [],
    };
  }

  const verifiedRequest: PolicyRequest = {
    ...request,
    context: {
      ...request.context,
      metadata: {
        ...request.context?.metadata,
        verifiedEvidenceIds: [...verifiedEvidenceIds],
      },
    },
  };
  const matched = rules
    .filter((rule) => ruleMatches(rule, verifiedRequest))
    .sort((a, b) => (b.priority ?? 0) - (a.priority ?? 0) || a.id.localeCompare(b.id));
  const deny = matched.find((rule) => rule.effect === 'deny');
  const approval = matched.find((rule) => rule.effect === 'require_approval');
  const allow = matched.find((rule) => rule.effect === 'allow');

  let outcome: PolicyDecision['outcome'];
  let reason: string;
  if (deny) {
    outcome = 'denied';
    reason = `denied-by:${deny.id}`;
  } else if (approval) {
    outcome = 'approval_required';
    reason = `approval-required-by:${approval.id}`;
  } else if (allow) {
    outcome = 'allowed';
    reason = `allowed-by:${allow.id}`;
  } else {
    outcome = mode === 'legacy' ? 'allowed' : 'denied';
    reason = mode === 'legacy' ? 'legacy-default-allow' : 'default-deny';
  }

  return {
    requestId,
    outcome,
    enforcedOutcome: mode === 'enforce' ? outcome : 'allowed',
    mode,
    reason,
    matchedRules: matched.map((rule) => rule.id),
    obligations: approval ? ['valid-human-approval'] : [],
  };
}

